"use client"

import * as React from "react"

import { useCssPx, useDragGesture, useLatestRef } from "../hooks"
import {
  disposeAutoScrollSession,
  prefersReducedMotion,
  startAutoScrollSession,
  type AutoScrollSession,
} from "../lib/df-dnd"
import { useDfStrings } from "../lib/df-intl"
import {
  anchorsFromBars,
  buildTimelineScale,
  formatTimelineDateRange,
  layoutTimelineBars,
  nudgeTimelineBar,
  reduceTimelineDrag,
  routeDependencyPaths,
  type TimelineBarRect,
  type TimelineDependencyEdge,
  type TimelineDragKind,
  type TimelineVisibleRange,
  type TimelineZoom,
} from "../lib/df-timeline"
import { useVirtualRows } from "../lib/df-virtual"
import { cn } from "../lib/utils"

const LOADING_ROW_COUNT = 8
const DEFAULT_UNIT_PX = 40
const DEFAULT_ROW_HEIGHT = 36
const DEFAULT_LABEL_WIDTH = 220

export type TimelineRow = {
  id: string
  label: React.ReactNode
  start?: string
  due?: string
  progress?: number
  /** CSS custom property name used as the bar fill, e.g. `--success`. */
  colorToken?: string
}

export type TimelineBarChange = {
  start: string
  due: string
}

export type TimelineProps = Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> & {
  rows: TimelineRow[]
  dependencies?: TimelineDependencyEdge[]
  zoom?: TimelineZoom
  visibleRange: TimelineVisibleRange
  loading?: boolean
  emptyContent?: React.ReactNode
  overscan?: number
  estimateRowSize?: number
  onBarChange?: (id: string, next: TimelineBarChange) => void
  onRowClick?: (id: string) => void
  renderRowMeta?: (row: TimelineRow) => React.ReactNode
}

type PointerDragSession = {
  pointerId: number
  kind: TimelineDragKind
  rowId: string
  originStart: string
  originDue: string
  originX: number
  originWidth: number
  startClientX: number
  scrollLeftAtStart: number
}

type DragPreview = {
  rowId: string
  kind: TimelineDragKind
  start: string
  due: string
  translateX: number
  widthScale: number
}

type KeyboardDraft = {
  rowId: string
  originStart: string
  originDue: string
  draftStart: string
  draftDue: string
}

function resolveBarDates(row: TimelineRow): TimelineBarChange | null {
  if (!row.start && !row.due) return null
  if (row.start && row.due) return { start: row.start, due: row.due }
  if (row.start) return { start: row.start, due: row.start }
  return { start: row.due!, due: row.due! }
}

function rowAriaName(
  row: TimelineRow,
  fallback: string
): string {
  return typeof row.label === "string" && row.label.trim()
    ? row.label
    : fallback
}

function Timeline({
  className,
  rows,
  dependencies = [],
  zoom = "day",
  visibleRange,
  loading = false,
  emptyContent,
  overscan = 6,
  estimateRowSize: estimateRowSizeProp,
  onBarChange,
  onRowClick,
  renderRowMeta,
  style,
  "aria-label": ariaLabel,
  ...props
}: TimelineProps) {
  const s = useDfStrings()
  const rootRef = React.useRef<HTMLDivElement>(null)
  const labelScrollRef = React.useRef<HTMLDivElement>(null)
  const gridScrollRef = React.useRef<HTMLDivElement>(null)
  const headerScrollRef = React.useRef<HTMLDivElement>(null)
  const syncingScrollRef = React.useRef(false)
  const dragPreviewRef = React.useRef<DragPreview | null>(null)
  const autoScrollSession = React.useRef<AutoScrollSession | null>(null)
  const barDrag = useDragGesture()

  const [liveMessage, setLiveMessage] = React.useState("")
  const [dragPreview, setDragPreview] = React.useState<DragPreview | null>(null)
  const [keyboardDraft, setKeyboardDraft] = React.useState<KeyboardDraft | null>(
    null
  )

  const unitPx = useCssPx(rootRef, "--df-timeline-unit-px", DEFAULT_UNIT_PX)
  const tokenRowHeight = useCssPx(
    rootRef,
    "--df-timeline-row-height",
    DEFAULT_ROW_HEIGHT
  )
  const rowHeight = estimateRowSizeProp ?? tokenRowHeight
  const labelWidth = useCssPx(
    rootRef,
    "--df-timeline-label-width",
    DEFAULT_LABEL_WIDTH
  )
  const stubPx = useCssPx(rootRef, "--df-timeline-dependency-stub", 8)
  const radiusPx = useCssPx(rootRef, "--df-timeline-dependency-radius", 4)

  const scale = React.useMemo(
    () =>
      buildTimelineScale({
        visibleRange,
        zoom,
        unitPx,
      }),
    [unitPx, visibleRange, zoom]
  )

  const effectiveRows = React.useMemo(() => {
    if (!keyboardDraft) return rows
    return rows.map((row) =>
      row.id === keyboardDraft.rowId
        ? {
            ...row,
            start: keyboardDraft.draftStart,
            due: keyboardDraft.draftDue,
          }
        : row
    )
  }, [keyboardDraft, rows])

  const barRects = React.useMemo(
    () =>
      layoutTimelineBars(
        effectiveRows.map((row) => ({
          id: row.id,
          start: row.start,
          due: row.due,
          progress: row.progress,
        })),
        scale
      ),
    [effectiveRows, scale]
  )

  const barById = React.useMemo(() => {
    const map = new Map<string, TimelineBarRect>()
    for (const rect of barRects) map.set(rect.id, rect)
    return map
  }, [barRects])

  const rowIndexById = React.useMemo(() => {
    const map = new Map<string, number>()
    effectiveRows.forEach((row, index) => map.set(row.id, index))
    return map
  }, [effectiveRows])

  const dependencyPaths = React.useMemo(() => {
    const anchors = anchorsFromBars(barRects, rowIndexById)
    return routeDependencyPaths(dependencies, anchors, {
      rowHeight,
      stubPx,
      radiusPx,
    })
  }, [barRects, dependencies, radiusPx, rowHeight, rowIndexById, stubPx])

  const { items, totalSize, measureElement } = useVirtualRows({
    count: loading || rows.length === 0 ? 0 : rows.length,
    estimateSize: rowHeight,
    getScrollElement: () => gridScrollRef.current,
    overscan,
  })

  const announce = React.useCallback((message: string) => {
    setLiveMessage(message)
  }, [])

  const syncLabelScroll = React.useCallback(() => {
    const grid = gridScrollRef.current
    const labels = labelScrollRef.current
    if (!grid || !labels || syncingScrollRef.current) return
    if (labels.scrollTop !== grid.scrollTop) {
      syncingScrollRef.current = true
      labels.scrollTop = grid.scrollTop
      syncingScrollRef.current = false
    }
  }, [])

  const syncHeaderScroll = React.useCallback(() => {
    const grid = gridScrollRef.current
    const header = headerScrollRef.current
    if (!grid || !header) return
    if (header.scrollLeft !== grid.scrollLeft) {
      header.scrollLeft = grid.scrollLeft
    }
  }, [])

  const onGridScroll = React.useCallback(() => {
    syncLabelScroll()
    syncHeaderScroll()
  }, [syncHeaderScroll, syncLabelScroll])

  const onLabelScroll = React.useCallback(() => {
    const grid = gridScrollRef.current
    const labels = labelScrollRef.current
    if (!grid || !labels || syncingScrollRef.current) return
    if (grid.scrollTop !== labels.scrollTop) {
      syncingScrollRef.current = true
      grid.scrollTop = labels.scrollTop
      syncingScrollRef.current = false
    }
  }, [])

  React.useEffect(() => {
    const header = headerScrollRef.current
    if (!header) return
    const onWheel = (event: WheelEvent) => {
      const grid = gridScrollRef.current
      if (!grid) return
      const deltaX =
        event.deltaX !== 0 ? event.deltaX : event.shiftKey ? event.deltaY : 0
      const deltaY =
        event.deltaX !== 0 || event.shiftKey ? 0 : event.deltaY
      if (deltaX === 0 && deltaY === 0) return
      event.preventDefault()
      if (deltaX !== 0) grid.scrollLeft += deltaX
      if (deltaY !== 0) grid.scrollTop += deltaY
    }
    header.addEventListener("wheel", onWheel, { passive: false })
    return () => header.removeEventListener("wheel", onWheel)
  }, [])

  const stopAutoScroll = React.useCallback(() => {
    disposeAutoScrollSession(autoScrollSession)
  }, [])

  const updateDragPreview = React.useCallback((next: DragPreview | null) => {
    dragPreviewRef.current = next
    setDragPreview(next)
  }, [])

  const commitBarChange = React.useCallback(
    (rowId: string, next: TimelineBarChange, origin: TimelineBarChange) => {
      if (next.start === origin.start && next.due === origin.due) {
        announce(s.timelineBarUnchanged)
        return
      }
      onBarChange?.(rowId, next)
      announce(
        s.timelineUpdated(formatTimelineDateRange(next.start, next.due))
      )
    },
    [announce, onBarChange, s]
  )

  const applyPointerDelta = React.useCallback(
    (session: PointerDragSession, clientX: number) => {
      const grid = gridScrollRef.current
      const scrollDelta = grid
        ? grid.scrollLeft - session.scrollLeftAtStart
        : 0
      const deltaPx = clientX - session.startClientX + scrollDelta
      const proposed = reduceTimelineDrag({
        kind: session.kind,
        origin: { start: session.originStart, due: session.originDue },
        deltaPx,
        scale,
      })

      let translateX = 0
      let widthScale = 1
      if (session.kind === "move") {
        translateX = scale.dateToX(proposed.start) - session.originX
      } else if (session.kind === "resize-end") {
        const nextWidth = Math.max(
          scale.unitPx,
          scale.dateToX(proposed.due) + scale.unitPx - session.originX
        )
        widthScale = nextWidth / Math.max(session.originWidth, 1)
      } else {
        const nextX = scale.dateToX(proposed.start)
        const nextWidth = Math.max(
          scale.unitPx,
          session.originX + session.originWidth - nextX
        )
        translateX = nextX - session.originX
        widthScale = nextWidth / Math.max(session.originWidth, 1)
      }

      updateDragPreview({
        rowId: session.rowId,
        kind: session.kind,
        start: proposed.start,
        due: proposed.due,
        translateX,
        widthScale,
      })
    },
    [scale, updateDragPreview]
  )

  const liveRef = useLatestRef({
    announce,
    applyPointerDelta,
    commitBarChange,
    stopAutoScroll,
    updateDragPreview,
    s,
  })

  const beginPointerDrag = React.useCallback(
    (
      event: React.PointerEvent<HTMLElement>,
      row: TimelineRow,
      kind: TimelineDragKind,
      rect: TimelineBarRect
    ) => {
      if (event.button !== 0 || (!row.start && !row.due)) return
      const dates = resolveBarDates(row)
      if (!dates) return
      event.preventDefault()
      event.stopPropagation()

      const originStart = scale.snapDate(dates.start)
      const originDue = scale.snapDate(dates.due)
      const session: PointerDragSession = {
        pointerId: event.pointerId,
        kind,
        rowId: row.id,
        originStart,
        originDue,
        originX: rect.x,
        originWidth: rect.width,
        startClientX: event.clientX,
        scrollLeftAtStart: gridScrollRef.current?.scrollLeft ?? 0,
      }
      setKeyboardDraft(null)
      updateDragPreview({
        rowId: row.id,
        kind,
        start: originStart,
        due: originDue,
        translateX: 0,
        widthScale: 1,
      })
      announce(
        kind === "move"
          ? s.timelineMovingBar(
              formatTimelineDateRange(originStart, originDue)
            )
          : s.timelineResizingBar(
              formatTimelineDateRange(originStart, originDue)
            )
      )
      stopAutoScroll()
      autoScrollSession.current = startAutoScrollSession({
        axis: "both",
        getContainer: () => gridScrollRef.current,
      })

      const onKeyDown = (keyEvent: KeyboardEvent) => {
        if (keyEvent.key !== "Escape") return
        keyEvent.preventDefault()
        barDrag.end("cancel")
      }
      window.addEventListener("keydown", onKeyDown)

      barDrag.begin(event, session, {
        onMove: (moveEvent, activeSession) => {
          autoScrollSession.current?.updatePointer(
            moveEvent.clientX,
            moveEvent.clientY
          )
          liveRef.current.applyPointerDelta(activeSession, moveEvent.clientX)
        },
        onEnd: (_event, activeSession, reason) => {
          window.removeEventListener("keydown", onKeyDown)
          const preview = dragPreviewRef.current
          dragPreviewRef.current = null
          setDragPreview(null)
          const live = liveRef.current
          live.stopAutoScroll()
          if (
            reason !== "up" ||
            !preview ||
            preview.rowId !== activeSession.rowId
          ) {
            if (reason !== "unmount") {
              live.announce(live.s.timelineBarDragCancelled)
            }
            return
          }
          live.commitBarChange(
            activeSession.rowId,
            { start: preview.start, due: preview.due },
            {
              start: activeSession.originStart,
              due: activeSession.originDue,
            }
          )
        },
      })
    },
    [
      announce,
      barDrag,
      liveRef,
      s,
      scale,
      stopAutoScroll,
      updateDragPreview,
    ]
  )

  const onBarKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLElement>, row: TimelineRow) => {
      const liveRow =
        keyboardDraft?.rowId === row.id
          ? {
              ...row,
              start: keyboardDraft.draftStart,
              due: keyboardDraft.draftDue,
            }
          : row
      const dates = resolveBarDates(liveRow)
      if (!dates) return

      if (event.key === "Escape") {
        if (!keyboardDraft || keyboardDraft.rowId !== row.id) return
        event.preventDefault()
        setKeyboardDraft(null)
        announce(s.timelineBarEditCancelled)
        return
      }

      if (event.key === "Enter") {
        if (!keyboardDraft || keyboardDraft.rowId !== row.id) return
        event.preventDefault()
        const next = {
          start: keyboardDraft.draftStart,
          due: keyboardDraft.draftDue,
        }
        const origin = {
          start: keyboardDraft.originStart,
          due: keyboardDraft.originDue,
        }
        setKeyboardDraft(null)
        commitBarChange(row.id, next, origin)
        return
      }

      if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return
      event.preventDefault()
      const units = event.key === "ArrowRight" ? 1 : -1
      const kind: TimelineDragKind = event.altKey
        ? "resize-start"
        : event.shiftKey
          ? "resize-end"
          : "move"
      const origin =
        keyboardDraft?.rowId === row.id
          ? {
              start: keyboardDraft.originStart,
              due: keyboardDraft.originDue,
            }
          : dates
      const next = nudgeTimelineBar({
        kind,
        origin: dates,
        units,
        scale,
      })
      setKeyboardDraft({
        rowId: row.id,
        originStart: origin.start,
        originDue: origin.due,
        draftStart: next.start,
        draftDue: next.due,
      })
      const range = formatTimelineDateRange(next.start, next.due)
      announce(
        kind === "move"
          ? s.timelineMovedCommit(range)
          : s.timelineResizedCommit(range)
      )
    },
    [announce, commitBarChange, keyboardDraft, s, scale]
  )

  const isEmpty = !loading && rows.length === 0
  const reducedMotion = prefersReducedMotion()
  const weekendColumns =
    zoom === "day"
      ? scale.fineColumns.filter((column) => column.isWeekend)
      : []

  return (
    <div
      {...props}
      ref={rootRef}
      data-df="timeline"
      data-zoom={zoom}
      data-loading={loading ? "true" : undefined}
      data-empty={isEmpty ? "true" : undefined}
      className={cn("df-timeline", className)}
      style={style}
      role="treegrid"
      aria-label={ariaLabel ?? s.timelineAriaLabel}
      aria-rowcount={loading ? LOADING_ROW_COUNT + 1 : rows.length + 1}
      aria-busy={loading || undefined}
    >
      <div className="df-timeline-chrome" data-df="timeline-chrome">
        <div
          className="df-timeline-corner"
          data-df="timeline-corner"
          style={{ width: labelWidth, minWidth: labelWidth }}
        >
          <span className="df-timeline-corner-label">{s.timelineNameColumn}</span>
        </div>
        <div
          ref={headerScrollRef}
          className="df-timeline-header-scroll"
          data-df="timeline-header-scroll"
        >
          <div
            className="df-timeline-header"
            data-df="timeline-header"
            style={{ width: scale.totalWidth }}
          >
            <div
              className="df-timeline-header-row"
              data-df="timeline-header-coarse"
            >
              {scale.coarseHeaders.map((cell) => (
                <div
                  key={cell.key}
                  className="df-timeline-header-cell"
                  style={{ left: cell.x, width: cell.width }}
                >
                  {cell.label}
                </div>
              ))}
            </div>
            <div
              className="df-timeline-header-row"
              data-df="timeline-header-fine"
            >
              {scale.fineHeaders.map((cell) => (
                <div
                  key={cell.key}
                  className="df-timeline-header-cell"
                  style={{ left: cell.x, width: cell.width }}
                >
                  {cell.label}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="df-timeline-body" data-df="timeline-body">
        <div
          ref={labelScrollRef}
          className="df-timeline-labels"
          data-df="timeline-labels"
          style={{ width: labelWidth, minWidth: labelWidth }}
          onScroll={onLabelScroll}
        >
          {loading ? (
            <div className="df-timeline-loading" data-df="timeline-loading">
              {Array.from({ length: LOADING_ROW_COUNT }, (_, index) => (
                <div
                  key={`label-loading-${index}`}
                  className="df-timeline-label-row"
                  style={{ height: rowHeight }}
                >
                  <span className="df-timeline-skeleton" />
                </div>
              ))}
            </div>
          ) : isEmpty ? null : (
            <div className="df-timeline-label-rows" style={{ height: totalSize }}>
              {items.map((item) => {
                const row = effectiveRows[item.index]
                if (!row) return null
                return (
                  <div
                    key={row.id}
                    ref={measureElement}
                    data-index={item.index}
                    className="df-timeline-label-row"
                    data-df="timeline-label-row"
                    role="row"
                    aria-rowindex={item.index + 2}
                    style={{
                      position: "absolute",
                      top: 0,
                      left: 0,
                      width: "100%",
                      height: item.size,
                      transform: `translateY(${item.start}px)`,
                    }}
                    onClick={() => onRowClick?.(row.id)}
                  >
                    <div className="df-timeline-label-main">
                      <span className="df-timeline-label-text">{row.label}</span>
                      {renderRowMeta ? (
                        <span className="df-timeline-label-meta">
                          {renderRowMeta(row)}
                        </span>
                      ) : null}
                    </div>
                  </div>
                )
              })}
            </div>
          )}
        </div>

        <div
          ref={gridScrollRef}
          className="df-timeline-grid"
          data-df="timeline-grid"
          onScroll={onGridScroll}
        >
          {loading ? (
            <div
              className="df-timeline-loading"
              data-df="timeline-loading"
              style={{ width: scale.totalWidth }}
            >
              {Array.from({ length: LOADING_ROW_COUNT }, (_, index) => (
                <div
                  key={`grid-loading-${index}`}
                  className="df-timeline-track-row"
                  style={{ height: rowHeight, width: scale.totalWidth }}
                >
                  <span className="df-timeline-skeleton df-timeline-skeleton-bar" />
                </div>
              ))}
            </div>
          ) : isEmpty ? (
            <div
              className="df-timeline-empty"
              data-df="timeline-empty"
              aria-live="polite"
            >
              {emptyContent ?? s.timelineEmpty}
            </div>
          ) : (
            <div
              className="df-timeline-tracks"
              data-df="timeline-tracks"
              style={{ height: totalSize, width: scale.totalWidth }}
            >
              {weekendColumns.map((column) => (
                <div
                  key={`weekend-${column.key}`}
                  className="df-timeline-weekend"
                  data-df="timeline-weekend"
                  style={{ left: column.x, width: column.width }}
                />
              ))}

              {scale.fineColumns.map((column) => (
                <div
                  key={`col-${column.key}`}
                  className="df-timeline-column-line"
                  style={{ left: column.x }}
                />
              ))}

              {scale.todayX !== null ? (
                <div
                  className="df-timeline-today"
                  data-df="timeline-today"
                  style={{ left: scale.todayX }}
                />
              ) : null}

              <svg
                className="df-timeline-dependencies"
                data-df="timeline-dependencies"
                width={scale.totalWidth}
                height={totalSize}
                aria-hidden
              >
                {dependencyPaths.map((path) => (
                  <path
                    key={`${path.fromId}-${path.toId}`}
                    d={path.d}
                    className="df-timeline-dependency-path"
                  />
                ))}
              </svg>

              {items.map((item) => {
                const row = effectiveRows[item.index]
                if (!row) return null
                const rect = barById.get(row.id)
                const preview =
                  dragPreview?.rowId === row.id ? dragPreview : null
                const color = row.colorToken
                  ? `var(${row.colorToken})`
                  : undefined
                const labelDates = preview
                  ? formatTimelineDateRange(preview.start, preview.due)
                  : formatTimelineDateRange(
                      row.start ?? row.due ?? "",
                      row.due ?? row.start ?? ""
                    )

                return (
                  <div
                    key={row.id}
                    className="df-timeline-track-row"
                    data-df="timeline-track-row"
                    role="row"
                    aria-rowindex={item.index + 2}
                    style={{
                      position: "absolute",
                      top: 0,
                      left: 0,
                      width: scale.totalWidth,
                      height: item.size,
                      transform: `translateY(${item.start}px)`,
                    }}
                  >
                    {rect ? (
                      <div
                        className="df-timeline-bar"
                        data-df="timeline-bar"
                        data-missing-start={
                          rect.missingStart ? "true" : undefined
                        }
                        data-missing-due={rect.missingDue ? "true" : undefined}
                        data-dragging={preview ? "true" : undefined}
                        role="gridcell"
                        tabIndex={0}
                        aria-label={`${rowAriaName(row, s.timelineItemFallback)} ${labelDates}`}
                        style={{
                          left: rect.x,
                          width: rect.width,
                          background: color,
                          transform: preview
                            ? `translateX(${preview.translateX}px) scaleX(${preview.widthScale})`
                            : undefined,
                          transformOrigin: "left center",
                          transition:
                            preview || reducedMotion
                              ? "none"
                              : "transform var(--df-duration-quick) var(--df-ease-standard)",
                        }}
                        onKeyDown={(event) => onBarKeyDown(event, row)}
                        onPointerDown={(event) =>
                          beginPointerDrag(event, row, "move", rect)
                        }
                      >
                        {rect.progress !== null ? (
                          <span
                            className="df-timeline-bar-progress"
                            style={{
                              width: `${Math.round(rect.progress * 100)}%`,
                            }}
                          />
                        ) : null}
                        <span
                          className="df-timeline-bar-handle df-timeline-bar-handle-start"
                          data-df="timeline-bar-handle"
                          data-edge="start"
                          onPointerDown={(event) =>
                            beginPointerDrag(event, row, "resize-start", rect)
                          }
                        />
                        <span
                          className="df-timeline-bar-handle df-timeline-bar-handle-end"
                          data-df="timeline-bar-handle"
                          data-edge="end"
                          onPointerDown={(event) =>
                            beginPointerDrag(event, row, "resize-end", rect)
                          }
                        />
                      </div>
                    ) : null}

                    {preview ? (
                      <div
                        className="df-timeline-ghost"
                        data-df="timeline-ghost"
                        style={{
                          left: scale.dateToX(preview.start),
                          width: Math.max(
                            scale.unitPx,
                            scale.dateToX(preview.due) +
                              scale.unitPx -
                              scale.dateToX(preview.start)
                          ),
                        }}
                      >
                        <span className="df-timeline-ghost-label">
                          {formatTimelineDateRange(preview.start, preview.due)}
                        </span>
                      </div>
                    ) : null}
                  </div>
                )
              })}
            </div>
          )}
        </div>
      </div>

      <div
        className="df-timeline-live"
        data-df="timeline-live"
        aria-live="polite"
        aria-atomic="true"
      >
        {liveMessage}
      </div>
    </div>
  )
}

export { Timeline }
export type { TimelineDependencyEdge, TimelineVisibleRange, TimelineZoom }

import {
  addUtcDays,
  formatUtcDate,
  startOfUtcDay,
  toDate,
} from "../df-date/index"

const MS_PER_DAY = 86_400_000

export type TimelineZoom = "day" | "week" | "month" | "quarter"

export type TimelineVisibleRange = {
  start: string
  end: string
}

export type TimelineHeaderCell = {
  key: string
  label: string
  start: string
  end: string
  x: number
  width: number
}

export type TimelineFineColumn = TimelineHeaderCell & {
  isWeekend: boolean
}

export type TimelineScale = {
  zoom: TimelineZoom
  rangeStart: string
  rangeEnd: string
  unitPx: number
  totalWidth: number
  fineColumns: TimelineFineColumn[]
  coarseHeaders: TimelineHeaderCell[]
  fineHeaders: TimelineHeaderCell[]
  todayX: number | null
  dateToX: (iso: string) => number
  xToDate: (px: number) => string
  snapDate: (iso: string) => string
  shiftDate: (iso: string, units: number) => string
  unitLabel: string
}

export type BuildTimelineScaleOptions = {
  visibleRange: TimelineVisibleRange
  zoom: TimelineZoom
  /** Pixels per fine tick unit. Typically read from `--df-timeline-unit-px`. */
  unitPx: number
  /** ISO date used for the today marker. Defaults to the current UTC day. */
  today?: string
}

type Span = {
  start: Date
  end: Date
  label: string
  key: string
  isWeekend: boolean
}

function assertPositiveUnitPx(unitPx: number): number {
  if (!Number.isFinite(unitPx) || unitPx <= 0) {
    throw new Error("unitPx must be a positive finite number")
  }
  return unitPx
}

function startOfUtcWeek(value: Date | string | number): Date {
  const day = startOfUtcDay(value)
  return addUtcDays(day, -day.getUTCDay())
}

function startOfUtcMonth(value: Date | string | number): Date {
  const day = startOfUtcDay(value)
  return new Date(Date.UTC(day.getUTCFullYear(), day.getUTCMonth(), 1))
}

function addUtcMonths(value: Date | string | number, months: number): Date {
  const day = startOfUtcDay(value)
  return new Date(
    Date.UTC(day.getUTCFullYear(), day.getUTCMonth() + months, 1)
  )
}

function startOfUtcQuarter(value: Date | string | number): Date {
  const day = startOfUtcDay(value)
  const quarterMonth = Math.floor(day.getUTCMonth() / 3) * 3
  return new Date(Date.UTC(day.getUTCFullYear(), quarterMonth, 1))
}

function monthLabel(date: Date): string {
  return date.toLocaleString("en-US", { month: "short", timeZone: "UTC" })
}

function yearLabel(date: Date): string {
  return String(date.getUTCFullYear())
}

function quarterLabel(date: Date): string {
  const q = Math.floor(date.getUTCMonth() / 3) + 1
  return `Q${q} ${date.getUTCFullYear()}`
}

function dayLabel(date: Date): string {
  return String(date.getUTCDate())
}

function weekLabel(date: Date): string {
  const end = addUtcDays(date, 6)
  return `${monthLabel(date)} ${dayLabel(date)}-${dayLabel(end)}`
}

function enumerateFineSpans(
  zoom: TimelineZoom,
  rangeStart: Date,
  rangeEndExclusive: Date
): Span[] {
  const spans: Span[] = []
  if (zoom === "day") {
    let cursor = rangeStart
    while (cursor.getTime() < rangeEndExclusive.getTime()) {
      const next = addUtcDays(cursor, 1)
      const weekday = cursor.getUTCDay()
      spans.push({
        start: cursor,
        end: next,
        label: dayLabel(cursor),
        key: formatUtcDate(cursor),
        isWeekend: weekday === 0 || weekday === 6,
      })
      cursor = next
    }
    return spans
  }

  if (zoom === "week") {
    let cursor = startOfUtcWeek(rangeStart)
    while (cursor.getTime() < rangeEndExclusive.getTime()) {
      const next = addUtcDays(cursor, 7)
      const visibleStart =
        cursor.getTime() < rangeStart.getTime() ? rangeStart : cursor
      if (visibleStart.getTime() < rangeEndExclusive.getTime()) {
        const visibleEnd =
          next.getTime() > rangeEndExclusive.getTime()
            ? rangeEndExclusive
            : next
        spans.push({
          start: visibleStart,
          end: visibleEnd,
          label: weekLabel(cursor),
          key: formatUtcDate(cursor),
          isWeekend: false,
        })
      }
      cursor = next
    }
    return spans
  }

  if (zoom === "month") {
    let cursor = startOfUtcMonth(rangeStart)
    while (cursor.getTime() < rangeEndExclusive.getTime()) {
      const next = addUtcMonths(cursor, 1)
      const visibleStart =
        cursor.getTime() < rangeStart.getTime() ? rangeStart : cursor
      if (visibleStart.getTime() < rangeEndExclusive.getTime()) {
        const visibleEnd =
          next.getTime() > rangeEndExclusive.getTime()
            ? rangeEndExclusive
            : next
        spans.push({
          start: visibleStart,
          end: visibleEnd,
          label: `${monthLabel(cursor)} ${yearLabel(cursor)}`,
          key: `${cursor.getUTCFullYear()}-${String(cursor.getUTCMonth() + 1).padStart(2, "0")}`,
          isWeekend: false,
        })
      }
      cursor = next
    }
    return spans
  }

  let cursor = startOfUtcQuarter(rangeStart)
  while (cursor.getTime() < rangeEndExclusive.getTime()) {
    const next = addUtcMonths(cursor, 3)
    const visibleStart =
      cursor.getTime() < rangeStart.getTime() ? rangeStart : cursor
    if (visibleStart.getTime() < rangeEndExclusive.getTime()) {
      const visibleEnd =
        next.getTime() > rangeEndExclusive.getTime()
          ? rangeEndExclusive
          : next
      spans.push({
        start: visibleStart,
        end: visibleEnd,
        label: quarterLabel(cursor),
        key: `${cursor.getUTCFullYear()}-Q${Math.floor(cursor.getUTCMonth() / 3) + 1}`,
        isWeekend: false,
      })
    }
    cursor = next
  }
  return spans
}

function enumerateCoarseSpans(
  zoom: TimelineZoom,
  fine: Span[]
): Array<{ start: Date; end: Date; label: string; key: string }> {
  if (fine.length === 0) return []

  if (zoom === "day" || zoom === "week") {
    const groups: Array<{ start: Date; end: Date; label: string; key: string }> =
      []
    for (const span of fine) {
      const monthStart = startOfUtcMonth(span.start)
      const key = `${monthStart.getUTCFullYear()}-${String(monthStart.getUTCMonth() + 1).padStart(2, "0")}`
      const label = `${monthLabel(monthStart)} ${yearLabel(monthStart)}`
      const last = groups[groups.length - 1]
      if (last && last.key === key) {
        last.end = span.end
      } else {
        groups.push({ start: span.start, end: span.end, label, key })
      }
    }
    return groups
  }

  if (zoom === "month") {
    const groups: Array<{ start: Date; end: Date; label: string; key: string }> =
      []
    for (const span of fine) {
      const key = yearLabel(span.start)
      const last = groups[groups.length - 1]
      if (last && last.key === key) {
        last.end = span.end
      } else {
        groups.push({
          start: span.start,
          end: span.end,
          label: key,
          key,
        })
      }
    }
    return groups
  }

  const groups: Array<{ start: Date; end: Date; label: string; key: string }> =
    []
  for (const span of fine) {
    const key = yearLabel(span.start)
    const last = groups[groups.length - 1]
    if (last && last.key === key) {
      last.end = span.end
    } else {
      groups.push({
        start: span.start,
        end: span.end,
        label: key,
        key,
      })
    }
  }
  return groups
}

function snapDateToZoom(iso: string, zoom: TimelineZoom): string {
  const day = startOfUtcDay(iso)
  if (zoom === "day") return formatUtcDate(day)
  if (zoom === "week") return formatUtcDate(startOfUtcWeek(day))
  if (zoom === "month") return formatUtcDate(startOfUtcMonth(day))
  return formatUtcDate(startOfUtcQuarter(day))
}

function shiftDateByZoom(
  iso: string,
  zoom: TimelineZoom,
  units: number
): string {
  const day = startOfUtcDay(iso)
  if (zoom === "day") return formatUtcDate(addUtcDays(day, units))
  if (zoom === "week") return formatUtcDate(addUtcDays(startOfUtcWeek(day), units * 7))
  if (zoom === "month") {
    return formatUtcDate(addUtcMonths(startOfUtcMonth(day), units))
  }
  return formatUtcDate(addUtcMonths(startOfUtcQuarter(day), units * 3))
}

function unitLabelForZoom(zoom: TimelineZoom): string {
  if (zoom === "day") return "day"
  if (zoom === "week") return "week"
  if (zoom === "month") return "month"
  return "quarter"
}

/**
 * Build a linear time scale for the visible range and zoom preset.
 * Fine columns share a fixed pixel width (`unitPx`); date mapping interpolates inside each column.
 */
export function buildTimelineScale(
  options: BuildTimelineScaleOptions
): TimelineScale {
  const unitPx = assertPositiveUnitPx(options.unitPx)
  const zoom = options.zoom
  const rangeStart = startOfUtcDay(options.visibleRange.start)
  const rangeEndInclusive = startOfUtcDay(options.visibleRange.end)
  if (rangeEndInclusive.getTime() < rangeStart.getTime()) {
    throw new Error("visibleRange.end must be on or after visibleRange.start")
  }
  const rangeEndExclusive = addUtcDays(rangeEndInclusive, 1)

  const fineSpans = enumerateFineSpans(zoom, rangeStart, rangeEndExclusive)
  const fineColumns: TimelineFineColumn[] = fineSpans.map((span, index) => ({
    key: span.key,
    label: span.label,
    start: formatUtcDate(span.start),
    end: formatUtcDate(addUtcDays(span.end, -1)),
    x: index * unitPx,
    width: unitPx,
    isWeekend: span.isWeekend,
  }))

  const coarseSpans = enumerateCoarseSpans(zoom, fineSpans)
  let coarseX = 0
  const coarseHeaders: TimelineHeaderCell[] = coarseSpans.map((span) => {
    const startMs = span.start.getTime()
    const endMs = span.end.getTime()
    const columns = fineSpans.filter(
      (fine) =>
        fine.start.getTime() >= startMs && fine.start.getTime() < endMs
    )
    const width = columns.length * unitPx
    const cell: TimelineHeaderCell = {
      key: span.key,
      label: span.label,
      start: formatUtcDate(span.start),
      end: formatUtcDate(addUtcDays(span.end, -1)),
      x: coarseX,
      width,
    }
    coarseX += width
    return cell
  })

  const fineHeaders: TimelineHeaderCell[] = fineColumns.map((column) => ({
    key: column.key,
    label: column.label,
    start: column.start,
    end: column.end,
    x: column.x,
    width: column.width,
  }))

  const totalWidth = fineColumns.length * unitPx

  const dateToX = (iso: string): number => {
    const date = toDate(iso)
    if (fineSpans.length === 0) return 0
    if (date.getTime() <= fineSpans[0]!.start.getTime()) return 0
    const last = fineSpans[fineSpans.length - 1]!
    if (date.getTime() >= last.end.getTime()) return totalWidth

    for (let i = 0; i < fineSpans.length; i += 1) {
      const span = fineSpans[i]!
      if (date.getTime() >= span.end.getTime()) continue
      const spanMs = Math.max(MS_PER_DAY, span.end.getTime() - span.start.getTime())
      const t = (date.getTime() - span.start.getTime()) / spanMs
      return i * unitPx + t * unitPx
    }
    return totalWidth
  }

  const xToDate = (px: number): string => {
    if (fineSpans.length === 0) return formatUtcDate(rangeStart)
    const clamped = Math.min(Math.max(px, 0), Math.max(totalWidth - Number.EPSILON, 0))
    const index = Math.min(
      fineSpans.length - 1,
      Math.max(0, Math.floor(clamped / unitPx))
    )
    const span = fineSpans[index]!
    const local = clamped - index * unitPx
    const spanMs = Math.max(MS_PER_DAY, span.end.getTime() - span.start.getTime())
    const ms = span.start.getTime() + (local / unitPx) * spanMs
    return formatUtcDate(startOfUtcDay(ms))
  }

  const todayIso = formatUtcDate(
    startOfUtcDay(options.today ?? new Date().toISOString())
  )
  const todayMs = startOfUtcDay(todayIso).getTime()
  const todayInRange =
    todayMs >= rangeStart.getTime() && todayMs < rangeEndExclusive.getTime()
  const todayX = todayInRange ? dateToX(todayIso) : null

  return {
    zoom,
    rangeStart: formatUtcDate(rangeStart),
    rangeEnd: formatUtcDate(rangeEndInclusive),
    unitPx,
    totalWidth,
    fineColumns,
    coarseHeaders,
    fineHeaders,
    todayX,
    dateToX,
    xToDate,
    snapDate: (iso) => snapDateToZoom(iso, zoom),
    shiftDate: (iso, units) => shiftDateByZoom(iso, zoom, units),
    unitLabel: unitLabelForZoom(zoom),
  }
}

import type { TimelineScale } from "./scale"

export type TimelineBarInput = {
  id: string
  start?: string | undefined
  due?: string | undefined
  progress?: number | undefined
}

export type TimelineBarRect = {
  id: string
  x: number
  width: number
  missingStart: boolean
  missingDue: boolean
  progress: number | null
}

export type LayoutTimelineBarsOptions = {
  /** Width used when one date is missing. Defaults to one fine unit. */
  openEndedWidth?: number
  /** Minimum rendered bar width in pixels. */
  minWidth?: number
}

function clampProgress(value: number | undefined): number | null {
  if (value === undefined || !Number.isFinite(value)) return null
  return Math.min(1, Math.max(0, value))
}

/**
 * Project row dates onto the scale as bar rectangles.
 * Rows missing both dates produce no bar. A single missing bound yields an open ended bar.
 */
export function layoutTimelineBars(
  rows: readonly TimelineBarInput[],
  scale: Pick<TimelineScale, "dateToX" | "unitPx" | "totalWidth">,
  options: LayoutTimelineBarsOptions = {}
): TimelineBarRect[] {
  const openEndedWidth = options.openEndedWidth ?? scale.unitPx
  const minWidth = options.minWidth ?? 1
  const rects: TimelineBarRect[] = []

  for (const row of rows) {
    const hasStart = typeof row.start === "string" && row.start.length > 0
    const hasDue = typeof row.due === "string" && row.due.length > 0
    if (!hasStart && !hasDue) continue

    const missingStart = !hasStart
    const missingDue = !hasDue
    let x = 0
    let width = openEndedWidth

    if (hasStart && hasDue) {
      const startX = scale.dateToX(row.start!)
      const dueX = scale.dateToX(row.due!)
      x = Math.min(startX, dueX)
      width = Math.max(minWidth, Math.abs(dueX - startX) + scale.unitPx)
    } else if (hasStart) {
      x = scale.dateToX(row.start!)
      width = Math.max(minWidth, openEndedWidth)
    } else {
      const dueX = scale.dateToX(row.due!)
      width = Math.max(minWidth, openEndedWidth)
      x = Math.max(0, dueX + scale.unitPx - width)
    }

    if (x + width < 0 || x > scale.totalWidth) continue

    rects.push({
      id: row.id,
      x,
      width,
      missingStart,
      missingDue,
      progress: clampProgress(row.progress),
    })
  }

  return rects
}

export function timelineBarsById(
  rects: readonly TimelineBarRect[]
): Map<string, TimelineBarRect> {
  const map = new Map<string, TimelineBarRect>()
  for (const rect of rects) map.set(rect.id, rect)
  return map
}

import type { TimelineBarRect } from "./bars"

export type TimelineDependencyEdge = {
  fromId: string
  toId: string
}

export type TimelineDependencyAnchor = {
  id: string
  x: number
  width: number
  rowIndex: number
}

export type TimelineDependencyPath = {
  fromId: string
  toId: string
  d: string
}

export type RouteDependencyPathsOptions = {
  rowHeight: number
  /** Horizontal stub before the first elbow. Defaults to 8. */
  stubPx?: number
  /** Corner radius for elbows. Defaults to 4. */
  radiusPx?: number
  /** Extra loop clearance for backward edges. Defaults to stubPx. */
  loopClearancePx?: number
}

function clampRadius(
  radius: number,
  horizontal: number,
  vertical: number
): number {
  const limit = Math.min(Math.abs(horizontal) / 2, Math.abs(vertical) / 2)
  if (!Number.isFinite(radius) || radius <= 0) return 0
  if (!Number.isFinite(limit) || limit <= 0) return 0
  return Math.min(radius, limit)
}

function rowCenterY(rowIndex: number, rowHeight: number): number {
  return rowIndex * rowHeight + rowHeight / 2
}

function forwardPath(input: {
  startX: number
  startY: number
  endX: number
  endY: number
  stub: number
  radius: number
}): string {
  const { startX, startY, endX, endY, stub, radius } = input
  if (startY === endY) {
    return `M ${startX} ${startY} H ${endX}`
  }
  const elbowX = startX + stub
  const deltaY = endY - startY
  const sign = deltaY >= 0 ? 1 : -1
  const r = clampRadius(radius, stub, deltaY)
  if (r === 0) {
    return `M ${startX} ${startY} H ${elbowX} V ${endY} H ${endX}`
  }
  return [
    `M ${startX} ${startY}`,
    `H ${elbowX - r}`,
    `Q ${elbowX} ${startY} ${elbowX} ${startY + sign * r}`,
    `V ${endY - sign * r}`,
    `Q ${elbowX} ${endY} ${elbowX + r} ${endY}`,
    `H ${endX}`,
  ].join(" ")
}

function backwardPath(input: {
  startX: number
  startY: number
  endX: number
  endY: number
  stub: number
  radius: number
  loopClearance: number
  rowHeight: number
  sameRow: boolean
}): string {
  const {
    startX,
    startY,
    endX,
    endY,
    stub,
    radius,
    loopClearance,
    rowHeight,
    sameRow,
  } = input
  const outX = startX + stub
  const loopX = Math.max(outX, endX + stub) + loopClearance
  const sign = sameRow ? 1 : endY >= startY ? 1 : -1
  const midY = sameRow ? startY + rowHeight * 0.65 * sign : endY
  const r = clampRadius(radius, loopClearance, Math.abs(midY - startY) || rowHeight)

  if (sameRow) {
    if (r === 0) {
      return [
        `M ${startX} ${startY}`,
        `H ${outX}`,
        `V ${midY}`,
        `H ${endX - stub}`,
        `V ${endY}`,
        `H ${endX}`,
      ].join(" ")
    }
    return [
      `M ${startX} ${startY}`,
      `H ${outX - r}`,
      `Q ${outX} ${startY} ${outX} ${startY + sign * r}`,
      `V ${midY - sign * r}`,
      `Q ${outX} ${midY} ${outX + r} ${midY}`,
      `H ${endX - stub - r}`,
      `Q ${endX - stub} ${midY} ${endX - stub} ${midY - sign * r}`,
      `V ${endY + sign * r}`,
      `Q ${endX - stub} ${endY} ${endX - stub + r} ${endY}`,
      `H ${endX}`,
    ].join(" ")
  }

  if (r === 0) {
    return `M ${startX} ${startY} H ${loopX} V ${endY} H ${endX}`
  }
  return [
    `M ${startX} ${startY}`,
    `H ${loopX - r}`,
    `Q ${loopX} ${startY} ${loopX} ${startY + sign * r}`,
    `V ${endY - sign * r}`,
    `Q ${loopX} ${endY} ${loopX - r} ${endY}`,
    `H ${endX}`,
  ].join(" ")
}

/**
 * Build SVG path strings for finish to start dependency edges.
 * Paths exit the right of the source bar and enter the left of the target bar.
 * Backward targets loop around with rounded elbows.
 */
export function routeDependencyPaths(
  edges: readonly TimelineDependencyEdge[],
  anchors: readonly TimelineDependencyAnchor[],
  options: RouteDependencyPathsOptions
): TimelineDependencyPath[] {
  const byId = new Map(anchors.map((anchor) => [anchor.id, anchor]))
  const stub = options.stubPx ?? 8
  const radius = options.radiusPx ?? 4
  const loopClearance = options.loopClearancePx ?? stub
  const rowHeight = options.rowHeight
  if (!Number.isFinite(rowHeight) || rowHeight <= 0) {
    throw new Error("rowHeight must be a positive finite number")
  }

  const paths: TimelineDependencyPath[] = []

  for (const edge of edges) {
    const from = byId.get(edge.fromId)
    const to = byId.get(edge.toId)
    if (!from || !to) continue

    const startX = from.x + from.width
    const startY = rowCenterY(from.rowIndex, rowHeight)
    const endX = to.x
    const endY = rowCenterY(to.rowIndex, rowHeight)
    const sameRow = from.rowIndex === to.rowIndex
    const forward = endX >= startX + stub

    const d = forward
      ? forwardPath({ startX, startY, endX, endY, stub, radius })
      : backwardPath({
          startX,
          startY,
          endX,
          endY,
          stub,
          radius,
          loopClearance,
          rowHeight,
          sameRow,
        })

    paths.push({ fromId: edge.fromId, toId: edge.toId, d })
  }

  return paths
}

export function anchorsFromBars(
  bars: readonly TimelineBarRect[],
  rowIndexById: ReadonlyMap<string, number>
): TimelineDependencyAnchor[] {
  const anchors: TimelineDependencyAnchor[] = []
  for (const bar of bars) {
    const rowIndex = rowIndexById.get(bar.id)
    if (rowIndex === undefined) continue
    anchors.push({
      id: bar.id,
      x: bar.x,
      width: bar.width,
      rowIndex,
    })
  }
  return anchors
}

import type { TimelineScale } from "./scale"

export type TimelineDragKind = "move" | "resize-start" | "resize-end"

export type TimelineDragOrigin = {
  start: string
  due: string
}

export type TimelineDragResult = {
  start: string
  due: string
}

export type ReduceTimelineDragInput = {
  kind: TimelineDragKind
  origin: TimelineDragOrigin
  deltaPx: number
  scale: Pick<
    TimelineScale,
    "dateToX" | "xToDate" | "snapDate" | "shiftDate" | "unitPx"
  >
}

function dayOrder(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0
}

function clampDueOnOrAfterStart(start: string, due: string): TimelineDragResult {
  if (dayOrder(due, start) < 0) return { start, due: start }
  return { start, due }
}

function unitsFromDeltaPx(deltaPx: number, unitPx: number): number {
  if (!Number.isFinite(deltaPx) || !Number.isFinite(unitPx) || unitPx <= 0) {
    return 0
  }
  return Math.round(deltaPx / unitPx)
}

/**
 * Pure drag reducer for bar move and edge resize.
 * Snaps to the active zoom unit and clamps so due is never before start.
 */
export function reduceTimelineDrag(
  input: ReduceTimelineDragInput
): TimelineDragResult {
  const { kind, origin, deltaPx, scale } = input
  const units = unitsFromDeltaPx(deltaPx, scale.unitPx)
  const originStart = scale.snapDate(origin.start)
  const originDue = scale.snapDate(origin.due)

  if (kind === "move") {
    return clampDueOnOrAfterStart(
      scale.shiftDate(originStart, units),
      scale.shiftDate(originDue, units)
    )
  }

  if (kind === "resize-start") {
    const nextStart = scale.shiftDate(originStart, units)
    if (dayOrder(nextStart, originDue) > 0) {
      return { start: originDue, due: originDue }
    }
    return { start: nextStart, due: originDue }
  }

  const nextDue = scale.shiftDate(originDue, units)
  if (dayOrder(nextDue, originStart) < 0) {
    return { start: originStart, due: originStart }
  }
  return { start: originStart, due: nextDue }
}

/**
 * Keyboard nudge helper. Positive units move later in time.
 */
export function nudgeTimelineBar(input: {
  kind: TimelineDragKind
  origin: TimelineDragOrigin
  units: number
  scale: Pick<TimelineScale, "snapDate" | "shiftDate">
}): TimelineDragResult {
  const originStart = input.scale.snapDate(input.origin.start)
  const originDue = input.scale.snapDate(input.origin.due)
  const units = Number.isFinite(input.units) ? Math.trunc(input.units) : 0

  if (input.kind === "move") {
    return clampDueOnOrAfterStart(
      input.scale.shiftDate(originStart, units),
      input.scale.shiftDate(originDue, units)
    )
  }
  if (input.kind === "resize-start") {
    const nextStart = input.scale.shiftDate(originStart, units)
    if (dayOrder(nextStart, originDue) > 0) {
      return { start: originDue, due: originDue }
    }
    return { start: nextStart, due: originDue }
  }
  const nextDue = input.scale.shiftDate(originDue, units)
  if (dayOrder(nextDue, originStart) < 0) {
    return { start: originStart, due: originStart }
  }
  return { start: originStart, due: nextDue }
}

export function formatTimelineDateRange(start: string, due: string): string {
  if (start === due) return start
  return `${start} to ${due}`
}

/** Owned date helpers. Prefer UTC day boundaries unless a timezone is supplied. */

export function toDate(value: Date | string | number): Date {
  const date = value instanceof Date ? new Date(value.getTime()) : new Date(value)
  if (Number.isNaN(date.getTime())) {
    throw new Error("Invalid date")
  }
  return date
}

export function startOfUtcDay(value: Date | string | number): Date {
  const date = toDate(value)
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()))
}

export function addUtcDays(value: Date | string | number, days: number): Date {
  const date = toDate(value)
  date.setUTCDate(date.getUTCDate() + days)
  return date
}

export function formatUtcDate(
  value: Date | string | number,
  pattern: "yyyy-mm-dd" | "iso" = "yyyy-mm-dd"
): string {
  const date = toDate(value)
  if (pattern === "iso") return date.toISOString()
  const year = date.getUTCFullYear()
  const month = String(date.getUTCMonth() + 1).padStart(2, "0")
  const day = String(date.getUTCDate()).padStart(2, "0")
  return `${year}-${month}-${day}`
}

export function utcDayRange(
  start: Date | string | number,
  end: Date | string | number
): { start: Date; end: Date } {
  const startDay = startOfUtcDay(start)
  const endDay = startOfUtcDay(end)
  if (endDay.getTime() < startDay.getTime()) {
    throw new Error("End day must be on or after start day")
  }
  return { start: startDay, end: endDay }
}

import {
  autoScrollDelta,
  type AutoScrollAxis,
  DF_DND_AUTO_SCROLL_MAX_VELOCITY_PX,
  DF_DND_AUTO_SCROLL_ZONE_PX,
} from "./auto-scroll"

export type AutoScrollContainerResolver = () => HTMLElement | null

export type AutoScrollSession = {
  updatePointer: (clientX: number, clientY: number) => void
  stop: () => void
}

export type AutoScrollSessionRef = {
  current: AutoScrollSession | null
}

/** Stop a session held in a ref and clear the ref. Safe when already idle. */
export function disposeAutoScrollSession(
  sessionRef: AutoScrollSessionRef
): void {
  sessionRef.current?.stop()
  sessionRef.current = null
}

/** True when the element can scroll on the given axis. */
export function canScrollOnAxis(
  element: HTMLElement,
  axis: "x" | "y"
): boolean {
  if (axis === "x") {
    return element.scrollWidth > element.clientWidth + 1
  }
  return element.scrollHeight > element.clientHeight + 1
}

/**
 * Nearest scrollable ancestor for the given axis, or the document scrolling element.
 */
export function findScrollableAncestor(
  start: HTMLElement | null,
  axis: AutoScrollAxis = "both"
): HTMLElement | null {
  if (typeof document === "undefined") return null
  let node: HTMLElement | null = start
  while (node && node !== document.body && node !== document.documentElement) {
    const style = window.getComputedStyle(node)
    const overflowY = style.overflowY
    const overflowX = style.overflowX
    const yScrollable =
      (overflowY === "auto" || overflowY === "scroll" || overflowY === "overlay") &&
      canScrollOnAxis(node, "y")
    const xScrollable =
      (overflowX === "auto" || overflowX === "scroll" || overflowX === "overlay") &&
      canScrollOnAxis(node, "x")
    if (axis === "y" && yScrollable) return node
    if (axis === "x" && xScrollable) return node
    if (axis === "both" && (yScrollable || xScrollable)) return node
    node = node.parentElement
  }
  const scrolling =
    (document.scrollingElement as HTMLElement | null) ?? document.documentElement
  return scrolling
}

/** Start a requestAnimationFrame loop that scrolls a container from pointer edge proximity. */
export function startAutoScrollSession(options: {
  getContainer: AutoScrollContainerResolver
  axis?: AutoScrollAxis
  zone?: number
  maxVelocity?: number
}): AutoScrollSession {
  let pointer: { x: number; y: number } | null = null
  let frame = 0
  let stopped = false
  const axis = options.axis ?? "both"
  const zone = options.zone ?? DF_DND_AUTO_SCROLL_ZONE_PX
  const maxVelocity = options.maxVelocity ?? DF_DND_AUTO_SCROLL_MAX_VELOCITY_PX

  const requestFrame = globalThis.requestAnimationFrame.bind(globalThis)
  const cancelFrame = globalThis.cancelAnimationFrame.bind(globalThis)

  const tick = () => {
    if (stopped) return
    frame = requestFrame(tick)
    if (!pointer) return
    const container = options.getContainer()
    if (!container) return
    const rect = container.getBoundingClientRect()
    const { dx, dy } = autoScrollDelta({
      clientX: pointer.x,
      clientY: pointer.y,
      left: rect.left,
      top: rect.top,
      right: rect.right,
      bottom: rect.bottom,
      axis,
      zone,
      maxVelocity,
    })
    if (dx !== 0) container.scrollLeft += dx
    if (dy !== 0) container.scrollTop += dy
  }

  frame = requestFrame(tick)

  return {
    updatePointer: (clientX, clientY) => {
      if (stopped) return
      pointer = { x: clientX, y: clientY }
    },
    stop: () => {
      if (stopped) return
      stopped = true
      cancelFrame(frame)
      pointer = null
      frame = 0
    },
  }
}

/** Pure edge proximity scroll velocity for pointer drag auto scroll. */

/** Edge zone thickness in CSS pixels where auto scroll activates. */
export const DF_DND_AUTO_SCROLL_ZONE_PX = 48

/** Peak scroll speed in CSS pixels per animation frame. */
export const DF_DND_AUTO_SCROLL_MAX_VELOCITY_PX = 28

export type AutoScrollAxis = "x" | "y" | "both"

/**
 * Signed scroll delta for one axis from pointer proximity to the start or end edge.
 * Negative values scroll toward the start; positive toward the end. Zero outside the zone.
 */
export function edgeScrollVelocity(options: {
  pointer: number
  start: number
  end: number
  zone?: number | undefined
  maxVelocity?: number | undefined
}): number {
  const zone = options.zone ?? DF_DND_AUTO_SCROLL_ZONE_PX
  const maxVelocity = options.maxVelocity ?? DF_DND_AUTO_SCROLL_MAX_VELOCITY_PX
  if (
    !Number.isFinite(options.pointer) ||
    !Number.isFinite(options.start) ||
    !Number.isFinite(options.end) ||
    zone <= 0 ||
    maxVelocity <= 0
  ) {
    return 0
  }

  const span = options.end - options.start
  if (span <= 0) return 0

  const effectiveZone = Math.min(zone, span / 2)
  const distFromStart = options.pointer - options.start
  const distFromEnd = options.end - options.pointer

  if (distFromStart < effectiveZone && distFromStart >= 0) {
    const t = 1 - distFromStart / effectiveZone
    return -maxVelocity * clampUnit(t)
  }
  if (distFromEnd < effectiveZone && distFromEnd >= 0) {
    const t = 1 - distFromEnd / effectiveZone
    return maxVelocity * clampUnit(t)
  }
  return 0
}

/** Axis scroll deltas for a rectangular scrollport and pointer position. */
export function autoScrollDelta(options: {
  clientX: number
  clientY: number
  left: number
  top: number
  right: number
  bottom: number
  axis?: AutoScrollAxis | undefined
  zone?: number | undefined
  maxVelocity?: number | undefined
}): { dx: number; dy: number } {
  const axis = options.axis ?? "both"
  const dx =
    axis === "y"
      ? 0
      : edgeScrollVelocity({
          pointer: options.clientX,
          start: options.left,
          end: options.right,
          zone: options.zone,
          maxVelocity: options.maxVelocity,
        })
  const dy =
    axis === "x"
      ? 0
      : edgeScrollVelocity({
          pointer: options.clientY,
          start: options.top,
          end: options.bottom,
          zone: options.zone,
          maxVelocity: options.maxVelocity,
        })
  return { dx, dy }
}

function clampUnit(value: number): number {
  if (!Number.isFinite(value)) return 0
  return Math.min(1, Math.max(0, value))
}

"use client"

import * as React from "react"
import { createPortal } from "react-dom"

import { useIsClient } from "../../hooks"
import { prefersReducedMotion } from "./motion"

export type DragOverlayState = {
  active: boolean
  activeId: string | null
  /** Ordered ids in the current drag payload. */
  ids: string[]
  count: number
  x: number
  y: number
}

export type DragOverlayRenderContext = {
  activeId: string
  ids: string[]
  count: number
  reducedMotion: boolean
}

export type DragOverlayProps = {
  state: DragOverlayState
  children: (context: DragOverlayRenderContext) => React.ReactNode
  /** Portal container. Defaults to document.body. */
  container?: Element | DocumentFragment | null
  className?: string
}

const INACTIVE_OVERLAY: DragOverlayState = {
  active: false,
  activeId: null,
  ids: [],
  count: 0,
  x: 0,
  y: 0,
}

/** Empty overlay state for hosts that have not started a drag. */
export function inactiveDragOverlayState(): DragOverlayState {
  return INACTIVE_OVERLAY
}

/**
 * Portal ghost that follows the pointer with translate3d.
 * Mount beside the sortable or board host when overlay mode is enabled.
 */
export function DragOverlay({
  state,
  children,
  container,
  className,
}: DragOverlayProps) {
  const mounted = useIsClient()

  if (!mounted || !state.active || state.activeId == null) return null

  const reducedMotion = prefersReducedMotion()
  const target = container ?? document.body
  const content = children({
    activeId: state.activeId,
    ids: state.ids,
    count: state.count,
    reducedMotion,
  })

  return createPortal(
    <div
      className={className ? `df-dnd-overlay ${className}` : "df-dnd-overlay"}
      data-df="dnd-overlay"
      data-count={state.count}
      data-reduced-motion={reducedMotion ? "true" : "false"}
      style={{
        transform: `translate3d(${state.x}px, ${state.y}px, 0)`,
      }}
    >
      <div
        className="df-dnd-overlay-lift"
        data-lift={reducedMotion ? "false" : "true"}
      >
        {content}
      </div>
    </div>,
    target
  )
}

/** Per slot drop indicator placement for hosts that render a drop line. */

export type DropIndicatorPlacement = "before" | "after" | "into"

export type DropIndicatorState = {
  targetId: string | null
  placement: DropIndicatorPlacement | null
}

export const EMPTY_DROP_INDICATOR: DropIndicatorState = {
  targetId: null,
  placement: null,
}

/**
 * Map an insertion index over non dragging item ids to a before/after indicator.
 * `into` is reserved for tree hosts that set it explicitly.
 */
export function dropIndicatorFromInsertIndex(
  insertIndex: number,
  itemIds: readonly string[]
): DropIndicatorState {
  if (itemIds.length === 0) return EMPTY_DROP_INDICATOR
  if (!Number.isFinite(insertIndex)) return EMPTY_DROP_INDICATOR
  if (insertIndex <= 0) {
    return { targetId: itemIds[0] ?? null, placement: "before" }
  }
  if (insertIndex >= itemIds.length) {
    return {
      targetId: itemIds[itemIds.length - 1] ?? null,
      placement: "after",
    }
  }
  return { targetId: itemIds[insertIndex] ?? null, placement: "before" }
}

/** True when the slot should show the given placement. */
export function isDropIndicatorActive(
  state: DropIndicatorState,
  id: string,
  placement: DropIndicatorPlacement
): boolean {
  return state.targetId === id && state.placement === placement
}

import { type BoardColumn } from "./reorder"

/**
 * Selected ids in visual order. When the active id is not selected, returns only the active id.
 */
export function orderedDragIds(
  visualOrder: readonly string[],
  selectedIds: ReadonlySet<string> | readonly string[] | undefined,
  activeId: string
): string[] {
  if (!selectedIds) return [activeId]
  const selected =
    selectedIds instanceof Set ? selectedIds : new Set(selectedIds)
  if (!selected.has(activeId)) return [activeId]
  return visualOrder.filter((id) => selected.has(id))
}

/** Flatten board column item ids in visual order. */
export function boardVisualOrder<T extends { id: string }>(
  columns: readonly BoardColumn<T>[]
): string[] {
  const ids: string[] = []
  for (const column of columns) {
    for (const item of column.items) ids.push(item.id)
  }
  return ids
}

/**
 * Remove a contiguous visual order group and splice it at `toIndex` in the remaining list.
 * `toIndex` is measured against the list after movers are removed.
 */
export function moveGroupInList<T extends { id: string }>(
  items: readonly T[],
  movingIds: readonly string[],
  toIndex: number
): T[] {
  if (movingIds.length === 0) return [...items]
  const movingSet = new Set(movingIds)
  const byId = new Map<string, T>()
  const remaining: T[] = []
  for (const item of items) {
    if (movingSet.has(item.id)) byId.set(item.id, item)
    else remaining.push(item)
  }
  const ordered: T[] = []
  for (const id of movingIds) {
    const item = byId.get(id)
    if (item) ordered.push(item)
  }
  if (ordered.length === 0) return [...items]
  const insertAt = Math.max(0, Math.min(toIndex, remaining.length))
  return [
    ...remaining.slice(0, insertAt),
    ...ordered,
    ...remaining.slice(insertAt),
  ]
}

/**
 * Move one or more cards into a column at `toIndex` (index in the destination after removal).
 * Movers keep the order given in `movingIds`.
 */
export function moveBoardGroup<T extends { id: string }>(
  columns: readonly BoardColumn<T>[],
  movingIds: readonly string[],
  toColumnId: string,
  toIndex: number
): BoardColumn<T>[] {
  if (movingIds.length === 0) return columns.map(cloneColumn)
  if (movingIds.length === 1) {
    const only = movingIds[0]
    if (!only) return columns.map(cloneColumn)
    return moveBoardGroupMany(columns, [only], toColumnId, toIndex)
  }
  return moveBoardGroupMany(columns, movingIds, toColumnId, toIndex)
}

function moveBoardGroupMany<T extends { id: string }>(
  columns: readonly BoardColumn<T>[],
  movingIds: readonly string[],
  toColumnId: string,
  toIndex: number
): BoardColumn<T>[] {
  const movingSet = new Set(movingIds)
  const byId = new Map<string, T>()
  const next = columns.map((column) => {
    const kept: T[] = []
    for (const item of column.items) {
      if (movingSet.has(item.id)) byId.set(item.id, item)
      else kept.push(item)
    }
    return { id: column.id, items: kept }
  })

  const ordered: T[] = []
  for (const id of movingIds) {
    const item = byId.get(id)
    if (item) ordered.push(item)
  }
  if (ordered.length === 0) return columns.map(cloneColumn)

  const toColumnIndex = next.findIndex((column) => column.id === toColumnId)
  if (toColumnIndex < 0) return columns.map(cloneColumn)
  const toColumn = next[toColumnIndex]
  if (!toColumn) return columns.map(cloneColumn)

  const insertAt = Math.max(0, Math.min(toIndex, toColumn.items.length))
  toColumn.items.splice(insertAt, 0, ...ordered)
  return next
}

function cloneColumn<T extends { id: string }>(
  column: BoardColumn<T>
): BoardColumn<T> {
  return { id: column.id, items: [...column.items] }
}

/** Pure reorder helpers for list and board drag. */

export function moveIndex<T>(items: readonly T[], from: number, to: number): T[] {
  if (from < 0 || from >= items.length) return [...items]
  const next = [...items]
  const [item] = next.splice(from, 1)
  if (item === undefined) return [...items]
  const clamped = Math.max(0, Math.min(to, next.length))
  next.splice(clamped, 0, item)
  return next
}

export type BoardColumn<T extends { id: string }> = {
  id: string
  items: T[]
}

/**
 * Move an item within one column or across columns.
 * `toIndex` is the insertion index in the destination column after removal.
 */
export function moveBoardItem<T extends { id: string }>(
  columns: readonly BoardColumn<T>[],
  itemId: string,
  toColumnId: string,
  toIndex: number
): BoardColumn<T>[] {
  let fromColumnIndex = -1
  let fromItemIndex = -1
  let moving: T | undefined

  for (let columnIndex = 0; columnIndex < columns.length; columnIndex += 1) {
    const column = columns[columnIndex]
    if (!column) continue
    const itemIndex = column.items.findIndex((item) => item.id === itemId)
    if (itemIndex >= 0) {
      fromColumnIndex = columnIndex
      fromItemIndex = itemIndex
      moving = column.items[itemIndex]
      break
    }
  }

  if (!moving || fromColumnIndex < 0) return columns.map(cloneColumn)

  const next = columns.map(cloneColumn)
  const fromColumn = next[fromColumnIndex]
  if (!fromColumn) return columns.map(cloneColumn)
  fromColumn.items.splice(fromItemIndex, 1)

  const toColumnIndex = next.findIndex((column) => column.id === toColumnId)
  if (toColumnIndex < 0) return columns.map(cloneColumn)
  const toColumn = next[toColumnIndex]
  if (!toColumn) return columns.map(cloneColumn)

  let insertAt = Math.max(0, Math.min(toIndex, toColumn.items.length))
  if (fromColumnIndex === toColumnIndex && fromItemIndex < insertAt) {
    insertAt -= 1
    insertAt = Math.max(0, insertAt)
  }
  toColumn.items.splice(insertAt, 0, moving)
  return next
}

function cloneColumn<T extends { id: string }>(
  column: BoardColumn<T>
): BoardColumn<T> {
  return { id: column.id, items: [...column.items] }
}

export function indexFromPointerY(
  clientY: number,
  itemRects: Array<{ id: string; top: number; bottom: number; height: number }>
): number {
  if (itemRects.length === 0) return 0
  for (let index = 0; index < itemRects.length; index += 1) {
    const rect = itemRects[index]
    if (!rect) continue
    const mid = rect.top + rect.height / 2
    if (clientY < mid) return index
  }
  return itemRects.length
}

/** Flat tree drop resolution for indent and outdent by pointer x offset. */

/** Horizontal pixels per depth step when resolving indent. */
export const DF_DND_TREE_INDENT_PX = 24

export type TreeFlatNode = {
  id: string
  parentId: string | null
  depth: number
}

export type TreeDropTarget = {
  targetParentId: string | null
  index: number
  depth: number
}

/** Depth from list relative pointer x, floored by the indent threshold. */
export function depthFromOffsetX(
  offsetX: number,
  indentThreshold: number = DF_DND_TREE_INDENT_PX
): number {
  if (!Number.isFinite(offsetX) || offsetX <= 0 || indentThreshold <= 0) {
    return 0
  }
  return Math.floor(offsetX / indentThreshold)
}

/** Collect a node id and every contiguous descendant in flat preorder. */
export function collectSubtreeIds(
  nodes: readonly TreeFlatNode[],
  rootId: string
): string[] {
  const ids = [rootId]
  const root = nodes.find((node) => node.id === rootId)
  if (!root) return ids
  const rootIndex = nodes.findIndex((node) => node.id === rootId)
  for (let i = rootIndex + 1; i < nodes.length; i += 1) {
    const node = nodes[i]
    if (!node || node.depth <= root.depth) break
    ids.push(node.id)
  }
  return ids
}

/** Union of subtrees for every dragged root id. */
export function collectDraggedSubtreeIds(
  nodes: readonly TreeFlatNode[],
  movingIds: readonly string[]
): Set<string> {
  const forbidden = new Set<string>()
  for (const id of movingIds) {
    for (const subtreeId of collectSubtreeIds(nodes, id)) {
      forbidden.add(subtreeId)
    }
  }
  return forbidden
}

/**
 * True when nesting under `targetParentId` would place a dragged node inside
 * its own subtree.
 */
export function isCyclicTreeParent(
  forbiddenParentIds: ReadonlySet<string>,
  targetParentId: string | null
): boolean {
  if (targetParentId == null) return false
  return forbiddenParentIds.has(targetParentId)
}

/**
 * Resolve a drop into `{ targetParentId, index, depth }` for a flat tree.
 * `insertIndex` is the gap index among nodes excluding the active id.
 * Depth is clamped to one level under the previous sibling and not above the next sibling.
 * Returns null when the resolved parent is the dragged node or any node in a dragged subtree.
 */
export function resolveTreeDrop(options: {
  nodes: readonly TreeFlatNode[]
  activeId: string
  insertIndex: number
  pointerOffsetX: number
  indentThreshold?: number
  /** Dragged roots; defaults to `[activeId]`. Subtree union is excluded as parents. */
  movingIds?: readonly string[]
}): TreeDropTarget | null {
  const indent = options.indentThreshold ?? DF_DND_TREE_INDENT_PX
  const movingIds =
    options.movingIds && options.movingIds.length > 0
      ? options.movingIds
      : [options.activeId]
  const forbiddenParents = collectDraggedSubtreeIds(options.nodes, movingIds)

  const remaining = options.nodes.filter((node) => node.id !== options.activeId)
  const insertIndex = Math.max(
    0,
    Math.min(
      Number.isFinite(options.insertIndex) ? options.insertIndex : 0,
      remaining.length
    )
  )

  if (remaining.length === 0) {
    return { targetParentId: null, index: 0, depth: 0 }
  }

  const previous = insertIndex > 0 ? remaining[insertIndex - 1] : null
  const next = insertIndex < remaining.length ? remaining[insertIndex] : null

  if (!previous) {
    return { targetParentId: null, index: 0, depth: 0 }
  }

  const maxDepth = previous.depth + 1
  const minDepth = next ? next.depth : 0
  let depth = depthFromOffsetX(options.pointerOffsetX, indent)
  depth = Math.max(minDepth, Math.min(maxDepth, depth))

  const targetParentId = parentIdForDepth(remaining, previous, depth)
  if (isCyclicTreeParent(forbiddenParents, targetParentId)) {
    return null
  }

  const index = siblingInsertIndex(remaining, insertIndex, targetParentId)
  return { targetParentId, index, depth }
}

/**
 * Move one node to a resolved tree drop target and recompute depths for its subtree.
 * Sibling order among non moved nodes is preserved.
 * A node cannot be dropped into its own subtree.
 */
export function applyTreeDrop<T extends TreeFlatNode>(
  nodes: readonly T[],
  activeId: string,
  target: TreeDropTarget | null,
  movingIds?: readonly string[]
): readonly T[] {
  if (target == null) return nodes

  const roots =
    movingIds && movingIds.length > 0 ? movingIds : [activeId]
  const forbiddenParents = collectDraggedSubtreeIds(nodes, roots)
  if (isCyclicTreeParent(forbiddenParents, target.targetParentId)) {
    return nodes
  }

  const activeIndex = nodes.findIndex((node) => node.id === activeId)
  if (activeIndex < 0) return nodes

  const active = nodes[activeIndex]
  if (!active) return nodes

  const subtreeIds = collectSubtreeIds(nodes, activeId)
  const subtreeSet = new Set(subtreeIds)
  const subtree = nodes.filter((node) => subtreeSet.has(node.id))
  const remaining = nodes.filter((node) => !subtreeSet.has(node.id))

  const depthDelta = target.depth - active.depth
  const moved = subtree.map((node) => {
    if (node.id === activeId) {
      return {
        ...node,
        parentId: target.targetParentId,
        depth: target.depth,
      }
    }
    return {
      ...node,
      depth: Math.max(0, node.depth + depthDelta),
    }
  })

  const siblingIds = remaining
    .filter((node) => node.parentId === target.targetParentId)
    .map((node) => node.id)
  const clampedIndex = Math.max(0, Math.min(target.index, siblingIds.length))

  const beforeSibling = siblingIds[clampedIndex]
  let insertAt = remaining.length
  if (beforeSibling) {
    const at = remaining.findIndex((node) => node.id === beforeSibling)
    if (at >= 0) insertAt = at
  } else if (siblingIds.length > 0) {
    const lastSibling = siblingIds[siblingIds.length - 1]
    if (lastSibling) {
      const lastIndex = remaining.findIndex((node) => node.id === lastSibling)
      if (lastIndex >= 0) {
        insertAt = lastIndex + subtreeSpanLength(remaining, lastSibling)
      }
    }
  } else {
    insertAt = flatInsertForEmptyParent(remaining, target.targetParentId)
  }

  return [
    ...remaining.slice(0, insertAt),
    ...moved,
    ...remaining.slice(insertAt),
  ]
}

function parentIdForDepth(
  remaining: readonly TreeFlatNode[],
  previous: TreeFlatNode,
  depth: number
): string | null {
  if (depth <= 0) return null
  if (depth === previous.depth + 1) return previous.id
  if (depth === previous.depth) return previous.parentId

  let cursor: TreeFlatNode | undefined = previous
  while (cursor && cursor.depth >= depth) {
    cursor = remaining.find((node) => node.id === cursor?.parentId)
  }
  if (cursor && cursor.depth === depth - 1) return cursor.id
  return previous.parentId
}

function siblingInsertIndex(
  remaining: readonly TreeFlatNode[],
  insertIndex: number,
  parentId: string | null
): number {
  let index = 0
  for (let i = 0; i < insertIndex; i += 1) {
    const node = remaining[i]
    if (node && node.parentId === parentId) index += 1
  }
  return index
}

function subtreeSpanLength(
  nodes: readonly TreeFlatNode[],
  rootId: string
): number {
  return collectSubtreeIds(nodes, rootId).length
}

function flatInsertForEmptyParent(
  remaining: readonly TreeFlatNode[],
  parentId: string | null
): number {
  if (parentId == null) return remaining.length
  const parentIndex = remaining.findIndex((node) => node.id === parentId)
  if (parentIndex < 0) return remaining.length
  let insertAt = parentIndex + 1
  const parentDepth = remaining[parentIndex]?.depth ?? 0
  for (let i = parentIndex + 1; i < remaining.length; i += 1) {
    const node = remaining[i]
    if (!node || node.depth <= parentDepth) break
    insertAt = i + 1
  }
  return insertAt
}

"use client"

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type RefObject,
} from "react"

import { type AutoScrollAxis } from "./auto-scroll"
import {
  disposeAutoScrollSession,
  findScrollableAncestor,
  startAutoScrollSession,
  type AutoScrollSession,
} from "./auto-scroll-runtime"
import {
  inactiveDragOverlayState,
  type DragOverlayState,
} from "./drag-overlay"
import {
  dropIndicatorFromInsertIndex,
  EMPTY_DROP_INDICATOR,
  type DropIndicatorState,
} from "./drop-indicator"
import { prefersReducedMotion } from "./motion"
import {
  boardVisualOrder,
  moveBoardGroup,
  orderedDragIds,
} from "./multi-drag"
import {
  indexFromPointerY,
  moveBoardItem,
  type BoardColumn,
} from "./reorder"

export type BoardCard = { id: string }

export type BoardAutoScrollOption =
  | boolean
  | {
      containerRef?: RefObject<HTMLElement | null>
      axis?: AutoScrollAxis
    }

export type BoardCardBindings = {
  ref: (node: HTMLElement | null) => void
  style: CSSProperties
  isDragging: boolean
  isPlaceholder: boolean
  attributes: {
    role: "button"
    tabIndex: number
    "aria-roledescription": string
    "aria-grabbed": boolean
    "aria-describedby": string
    "data-df-dnd-placeholder"?: boolean
    "data-df-drop-indicator"?: "before" | "after" | "into"
  }
  listeners: {
    onPointerDown: (event: ReactPointerEvent) => void
    onKeyDown: (event: KeyboardEvent) => void
  }
}

export type BoardColumnBindings = {
  ref: (node: HTMLElement | null) => void
  "data-df-board-column": string
  "data-df-drop-active": boolean
}

type PendingDrop = {
  columnId: string
  index: number
}

export function useBoardDnd<T extends BoardCard>(options: {
  columns: BoardColumn<T>[]
  onChange: (columns: BoardColumn<T>[]) => void
  disabled?: boolean
  /** Opt in edge auto scroll while pointer dragging. */
  autoScroll?: BoardAutoScrollOption
  /** Opt in portal ghost; host mounts `DragOverlay` with `overlay`. */
  overlay?: boolean
  /** Opt in multi item drag when the active id is in this set. */
  selectedIds?: ReadonlySet<string> | readonly string[]
  /** Called with ordered movers and insertion point after a successful drop. */
  onDropCommit?: (commit: {
    columns: BoardColumn<T>[]
    movingIds: string[]
    columnId: string
    insertIndex: number
  }) => void
  /** Opt in per slot drop indicator state. */
  dropIndicators?: boolean
}) {
  const {
    columns,
    onChange,
    disabled = false,
    autoScroll = false,
    overlay = false,
    selectedIds,
    onDropCommit,
    dropIndicators = false,
  } = options
  const instructionsId = useId()
  const cardNodes = useRef(new Map<string, HTMLElement>())
  const columnNodes = useRef(new Map<string, HTMLElement>())
  const columnsRef = useRef(columns)
  const selectedRef = useRef(selectedIds)

  useEffect(() => {
    columnsRef.current = columns
  }, [columns])

  useEffect(() => {
    selectedRef.current = selectedIds
  }, [selectedIds])

  const [activeId, setActiveId] = useState<string | null>(null)
  const [overColumnId, setOverColumnId] = useState<string | null>(null)
  const [keyboardActiveId, setKeyboardActiveId] = useState<string | null>(null)
  const [liveMessage, setLiveMessage] = useState("")
  const [overlayState, setOverlayState] = useState<DragOverlayState>(
    inactiveDragOverlayState
  )
  const [dropIndicator, setDropIndicator] =
    useState<DropIndicatorState>(EMPTY_DROP_INDICATOR)
  const [dragIds, setDragIds] = useState<string[]>([])
  const pointerId = useRef<number | null>(null)
  const pendingDrop = useRef<PendingDrop | null>(null)
  const movingIdsRef = useRef<string[]>([])
  const autoScrollSession = useRef<AutoScrollSession | null>(null)

  const announce = useCallback((message: string) => {
    setLiveMessage(message)
  }, [])

  const findLocation = useCallback((itemId: string, source = columns) => {
    for (let columnIndex = 0; columnIndex < source.length; columnIndex += 1) {
      const column = source[columnIndex]
      if (!column) continue
      const itemIndex = column.items.findIndex((item) => item.id === itemId)
      if (itemIndex >= 0) {
        return { columnId: column.id, columnIndex, itemIndex }
      }
    }
    return null
  }, [columns])

  const setCardNode = useCallback((id: string, node: HTMLElement | null) => {
    if (node) cardNodes.current.set(id, node)
    else cardNodes.current.delete(id)
  }, [])

  const setColumnNode = useCallback((id: string, node: HTMLElement | null) => {
    if (node) columnNodes.current.set(id, node)
    else columnNodes.current.delete(id)
  }, [])

  const columnFromPoint = useCallback((clientX: number, clientY: number) => {
    for (const [columnId, node] of columnNodes.current) {
      const rect = node.getBoundingClientRect()
      if (
        clientX >= rect.left &&
        clientX <= rect.right &&
        clientY >= rect.top &&
        clientY <= rect.bottom
      ) {
        return columnId
      }
    }
    return null
  }, [])

  const resolveMovingIds = useCallback((id: string, source: BoardColumn<T>[]) => {
    return orderedDragIds(boardVisualOrder(source), selectedRef.current, id)
  }, [])

  const stopAutoScroll = useCallback(() => {
    disposeAutoScrollSession(autoScrollSession)
  }, [])

  const startAutoScroll = useCallback(
    (origin: HTMLElement | null) => {
      if (!autoScroll) return
      stopAutoScroll()
      const config = typeof autoScroll === "object" ? autoScroll : {}
      const axis = config.axis ?? "both"
      autoScrollSession.current = startAutoScrollSession({
        axis,
        getContainer: () =>
          config.containerRef?.current ??
          findScrollableAncestor(origin, axis),
      })
    },
    [autoScroll, stopAutoScroll]
  )

  const clearDragChrome = useCallback(() => {
    setOverlayState(inactiveDragOverlayState())
    setDropIndicator(EMPTY_DROP_INDICATOR)
    setDragIds([])
    movingIdsRef.current = []
    stopAutoScroll()
  }, [stopAutoScroll])

  const commitDrop = useCallback(
    (
      current: BoardColumn<T>[],
      movingIds: string[],
      columnId: string,
      insertIndex: number
    ) => {
      const next = moveBoardGroup(current, movingIds, columnId, insertIndex)
      const unchanged = columnsEqual(current, next)
      if (unchanged) {
        announce("Board move finished")
        return
      }
      onChange(next)
      onDropCommit?.({
        columns: next,
        movingIds,
        columnId,
        insertIndex,
      })
      announce(
        movingIds.length > 1
          ? `Moved ${movingIds.length} cards to column ${columnId}, position ${insertIndex + 1}`
          : `Moved card to column ${columnId}, position ${insertIndex + 1}`
      )
    },
    [announce, onChange, onDropCommit]
  )

  useEffect(() => {
    if (pointerId.current === null || !activeId) return

    const onMove = (event: PointerEvent) => {
      if (event.pointerId !== pointerId.current) return
      const current = columnsRef.current
      const columnId = columnFromPoint(event.clientX, event.clientY)
      if (!columnId) return
      setOverColumnId(columnId)
      const column = current.find((entry) => entry.id === columnId)
      if (!column) return
      const moving = new Set(movingIdsRef.current)
      const visibleIds = column.items
        .filter((item) => !moving.has(item.id))
        .map((item) => item.id)
      const rects = visibleIds
        .map((id) => {
          const node = cardNodes.current.get(id)
          if (!node) return null
          const rect = node.getBoundingClientRect()
          return {
            id,
            top: rect.top,
            bottom: rect.bottom,
            height: rect.height,
          }
        })
        .filter((entry): entry is NonNullable<typeof entry> => entry !== null)
      const insertIndex = indexFromPointerY(event.clientY, rects)
      pendingDrop.current = { columnId, index: insertIndex }
      if (dropIndicators) {
        setDropIndicator(dropIndicatorFromInsertIndex(insertIndex, visibleIds))
      }
      autoScrollSession.current?.updatePointer(event.clientX, event.clientY)
      if (overlay) {
        setOverlayState({
          active: true,
          activeId,
          ids: movingIdsRef.current,
          count: movingIdsRef.current.length,
          x: event.clientX,
          y: event.clientY,
        })
      }
    }

    const onUp = (event: PointerEvent) => {
      if (event.pointerId !== pointerId.current) return
      const current = columnsRef.current
      const drop = pendingDrop.current
      const movingIds = movingIdsRef.current
      pointerId.current = null
      pendingDrop.current = null
      setActiveId(null)
      setOverColumnId(null)
      clearDragChrome()
      if (!drop || movingIds.length === 0) {
        announce("Board move finished")
        return
      }
      commitDrop(current, movingIds, drop.columnId, drop.index)
    }

    window.addEventListener("pointermove", onMove)
    window.addEventListener("pointerup", onUp)
    window.addEventListener("pointercancel", onUp)
    return () => {
      window.removeEventListener("pointermove", onMove)
      window.removeEventListener("pointerup", onUp)
      window.removeEventListener("pointercancel", onUp)
      stopAutoScroll()
    }
  }, [
    activeId,
    announce,
    clearDragChrome,
    columnFromPoint,
    commitDrop,
    dropIndicators,
    overlay,
    stopAutoScroll,
  ])

  const getColumnProps = useCallback(
    (columnId: string): BoardColumnBindings => ({
      ref: (node) => setColumnNode(columnId, node),
      "data-df-board-column": columnId,
      "data-df-drop-active": overColumnId === columnId,
    }),
    [overColumnId, setColumnNode]
  )

  const getCardProps = useCallback(
    (id: string): BoardCardBindings => {
      const location = findLocation(id)
      const inPayload = dragIds.includes(id)
      const isDragging =
        activeId === id || keyboardActiveId === id || inPayload
      const isPlaceholder = Boolean(overlay && activeId && inPayload)
      const reduced = prefersReducedMotion()
      const indicatorPlacement =
        dropIndicators && dropIndicator.targetId === id
          ? (dropIndicator.placement ?? undefined)
          : undefined

      return {
        ref: (node) => setCardNode(id, node),
        isDragging,
        isPlaceholder,
        style: {
          opacity: isPlaceholder
            ? undefined
            : isDragging
              ? "var(--opacity-subtle)"
              : undefined,
          transform:
            !overlay && isDragging && activeId === id && !reduced
              ? "scale(var(--df-dnd-lift-scale))"
              : undefined,
          transition: reduced
            ? "none"
            : "transform var(--df-duration-quick) var(--df-ease-standard), opacity var(--df-duration-quick) var(--df-ease-standard)",
          touchAction: "none",
          zIndex: isDragging && !overlay ? "var(--z-raised)" : undefined,
        },
        attributes: {
          role: "button",
          tabIndex: disabled ? -1 : 0,
          "aria-roledescription": "board card",
          "aria-grabbed": isDragging,
          "aria-describedby": instructionsId,
          ...(isPlaceholder ? { "data-df-dnd-placeholder": true } : null),
          ...(indicatorPlacement
            ? { "data-df-drop-indicator": indicatorPlacement }
            : null),
        },
        listeners: {
          onPointerDown: (event) => {
            if (disabled || event.button !== 0) return
            event.preventDefault()
            const movingIds = resolveMovingIds(id, columns)
            pointerId.current = event.pointerId
            pendingDrop.current = location
              ? { columnId: location.columnId, index: location.itemIndex }
              : null
            movingIdsRef.current = movingIds
            setDragIds(movingIds)
            setActiveId(id)
            setKeyboardActiveId(null)
            setOverColumnId(location?.columnId ?? null)
            startAutoScroll(event.currentTarget as HTMLElement)
            if (overlay) {
              setOverlayState({
                active: true,
                activeId: id,
                ids: movingIds,
                count: movingIds.length,
                x: event.clientX,
                y: event.clientY,
              })
            }
            announce(
              movingIds.length > 1
                ? `Picked up ${movingIds.length} board cards`
                : "Picked up board card"
            )
            ;(event.currentTarget as HTMLElement).setPointerCapture?.(
              event.pointerId
            )
          },
          onKeyDown: (event) => {
            if (disabled || !location) return
            if (event.key === " " || event.key === "Enter") {
              event.preventDefault()
              if (keyboardActiveId === id) {
                setKeyboardActiveId(null)
                clearDragChrome()
                announce("Card dropped")
                return
              }
              const movingIds = resolveMovingIds(id, columns)
              movingIdsRef.current = movingIds
              setDragIds(movingIds)
              setKeyboardActiveId(id)
              setActiveId(null)
              announce(
                movingIds.length > 1
                  ? `${movingIds.length} cards grabbed. Arrow keys move within or across columns. Space drops. Escape cancels.`
                  : "Card grabbed. Arrow keys move within or across columns. Space drops. Escape cancels."
              )
              return
            }
            if (keyboardActiveId !== id) return
            if (event.key === "Escape") {
              event.preventDefault()
              setKeyboardActiveId(null)
              clearDragChrome()
              announce("Board move cancelled")
              return
            }
            const movingIds =
              movingIdsRef.current.length > 0
                ? movingIdsRef.current
                : resolveMovingIds(id, columns)
            if (event.key === "ArrowUp" || event.key === "ArrowDown") {
              event.preventDefault()
              const delta = event.key === "ArrowUp" ? -1 : 1
              if (movingIds.length <= 1) {
                const toIndex = location.itemIndex + delta
                if (toIndex < 0) return
                onChange(
                  moveBoardItem(columns, id, location.columnId, toIndex)
                )
                announce(`Moved within column to position ${toIndex + 1}`)
                return
              }
              const column = columns[location.columnIndex]
              if (!column) return
              let insertAmong = 0
              for (const item of column.items) {
                if (item.id === movingIds[0]) break
                if (!movingIds.includes(item.id)) insertAmong += 1
              }
              const remainingInColumn = column.items.filter(
                (item) => !movingIds.includes(item.id)
              ).length
              const nextInsert = insertAmong + delta
              if (nextInsert < 0 || nextInsert > remainingInColumn) return
              commitDrop(columns, movingIds, location.columnId, nextInsert)
              return
            }
            if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
              event.preventDefault()
              const columnDelta = event.key === "ArrowLeft" ? -1 : 1
              const nextColumn = columns[location.columnIndex + columnDelta]
              if (!nextColumn) return
              const toIndex = Math.min(
                location.itemIndex,
                nextColumn.items.length
              )
              if (movingIds.length <= 1) {
                onChange(moveBoardItem(columns, id, nextColumn.id, toIndex))
                announce(`Moved card to column ${nextColumn.id}`)
                return
              }
              commitDrop(columns, movingIds, nextColumn.id, toIndex)
            }
          },
        },
      }
    },
    [
      activeId,
      announce,
      clearDragChrome,
      columns,
      commitDrop,
      disabled,
      dragIds,
      dropIndicator.placement,
      dropIndicator.targetId,
      dropIndicators,
      findLocation,
      instructionsId,
      keyboardActiveId,
      onChange,
      overlay,
      resolveMovingIds,
      setCardNode,
      startAutoScroll,
    ]
  )

  return {
    activeId: activeId ?? keyboardActiveId,
    overColumnId,
    getCardProps,
    getColumnProps,
    instructionsId,
    instructions:
      "Press Space or Enter to pick up a card. Arrow keys move it. Space or Enter drops. Escape cancels.",
    liveMessage,
    overlay: overlayState,
    dropIndicator,
    movingIds: dragIds,
  }
}

function columnsEqual<T extends { id: string }>(
  left: readonly BoardColumn<T>[],
  right: readonly BoardColumn<T>[]
): boolean {
  if (left.length !== right.length) return false
  for (let i = 0; i < left.length; i += 1) {
    const a = left[i]
    const b = right[i]
    if (!a || !b || a.id !== b.id || a.items.length !== b.items.length) {
      return false
    }
    for (let j = 0; j < a.items.length; j += 1) {
      if (a.items[j]?.id !== b.items[j]?.id) return false
    }
  }
  return true
}

"use client"

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type RefObject,
} from "react"

import { type AutoScrollAxis } from "./auto-scroll"
import {
  disposeAutoScrollSession,
  findScrollableAncestor,
  startAutoScrollSession,
  type AutoScrollSession,
} from "./auto-scroll-runtime"
import {
  inactiveDragOverlayState,
  type DragOverlayState,
} from "./drag-overlay"
import {
  dropIndicatorFromInsertIndex,
  EMPTY_DROP_INDICATOR,
  type DropIndicatorState,
} from "./drop-indicator"
import { prefersReducedMotion } from "./motion"
import { moveGroupInList, orderedDragIds } from "./multi-drag"
import { indexFromPointerY, moveIndex } from "./reorder"

export type SortableItem = { id: string }

export type SortableAutoScrollOption =
  | boolean
  | {
      containerRef?: RefObject<HTMLElement | null>
      axis?: AutoScrollAxis
    }

export type SortableItemBindings = {
  ref: (node: HTMLElement | null) => void
  style: CSSProperties
  isDragging: boolean
  isPlaceholder: boolean
  attributes: {
    role: "button"
    tabIndex: number
    "aria-roledescription": string
    "aria-grabbed": boolean
    "aria-describedby": string
    "data-df-dnd-placeholder"?: boolean
    "data-df-drop-indicator"?: "before" | "after" | "into"
  }
  listeners: {
    onPointerDown: (event: ReactPointerEvent) => void
    onKeyDown: (event: KeyboardEvent) => void
  }
}

export function useSortableList<T extends SortableItem>(options: {
  items: T[]
  onReorder: (items: T[]) => void
  disabled?: boolean
  /** Opt in edge auto scroll while pointer dragging. */
  autoScroll?: SortableAutoScrollOption
  /** Opt in portal ghost; host mounts `DragOverlay` with `overlay`. */
  overlay?: boolean
  /** Opt in multi item drag when the active id is in this set. */
  selectedIds?: ReadonlySet<string> | readonly string[]
  /** Called with ordered movers and insert index after a successful drop. */
  onDropCommit?: (commit: {
    items: T[]
    movingIds: string[]
    insertIndex: number
  }) => void
  /** Opt in per slot drop indicator state. */
  dropIndicators?: boolean
}) {
  const {
    items,
    onReorder,
    disabled = false,
    autoScroll = false,
    overlay = false,
    selectedIds,
    onDropCommit,
    dropIndicators = false,
  } = options
  const instructionsId = useId()
  const itemNodes = useRef(new Map<string, HTMLElement>())
  const itemsRef = useRef(items)
  const selectedRef = useRef(selectedIds)

  useEffect(() => {
    itemsRef.current = items
  }, [items])

  useEffect(() => {
    selectedRef.current = selectedIds
  }, [selectedIds])

  const [activeId, setActiveId] = useState<string | null>(null)
  const [keyboardActiveId, setKeyboardActiveId] = useState<string | null>(null)
  const [liveMessage, setLiveMessage] = useState("")
  const [overlayState, setOverlayState] = useState<DragOverlayState>(
    inactiveDragOverlayState
  )
  const [dropIndicator, setDropIndicator] =
    useState<DropIndicatorState>(EMPTY_DROP_INDICATOR)
  const [dragIds, setDragIds] = useState<string[]>([])
  const pointerId = useRef<number | null>(null)
  const pendingToIndex = useRef<number | null>(null)
  const movingIdsRef = useRef<string[]>([])
  const autoScrollSession = useRef<AutoScrollSession | null>(null)

  const setNode = useCallback((id: string, node: HTMLElement | null) => {
    if (node) itemNodes.current.set(id, node)
    else itemNodes.current.delete(id)
  }, [])

  const announce = useCallback((message: string) => {
    setLiveMessage(message)
  }, [])

  const resolveMovingIds = useCallback((id: string, source: T[]) => {
    return orderedDragIds(
      source.map((item) => item.id),
      selectedRef.current,
      id
    )
  }, [])

  const stopAutoScroll = useCallback(() => {
    disposeAutoScrollSession(autoScrollSession)
  }, [])

  const startAutoScroll = useCallback(
    (origin: HTMLElement | null) => {
      if (!autoScroll) return
      stopAutoScroll()
      const config = typeof autoScroll === "object" ? autoScroll : {}
      const axis = config.axis ?? "y"
      autoScrollSession.current = startAutoScrollSession({
        axis,
        getContainer: () =>
          config.containerRef?.current ??
          findScrollableAncestor(origin, axis),
      })
    },
    [autoScroll, stopAutoScroll]
  )

  const clearDragChrome = useCallback(() => {
    setOverlayState(inactiveDragOverlayState())
    setDropIndicator(EMPTY_DROP_INDICATOR)
    setDragIds([])
    movingIdsRef.current = []
    stopAutoScroll()
  }, [stopAutoScroll])

  const commitMove = useCallback(
    (current: T[], movingIds: string[], insertIndex: number) => {
      const next = moveGroupInList(current, movingIds, insertIndex)
      const unchanged =
        next.length === current.length &&
        next.every((item, index) => item.id === current[index]?.id)
      if (unchanged) {
        announce("Reorder finished")
        return
      }
      onReorder(next)
      onDropCommit?.({ items: next, movingIds, insertIndex })
      announce(
        movingIds.length > 1
          ? `Moved ${movingIds.length} items to position ${insertIndex + 1}`
          : `Moved item to position ${insertIndex + 1} of ${current.length}`
      )
    },
    [announce, onDropCommit, onReorder]
  )

  useEffect(() => {
    if (pointerId.current === null || !activeId) return

    const onMove = (event: PointerEvent) => {
      if (event.pointerId !== pointerId.current) return
      const current = itemsRef.current
      const moving = new Set(movingIdsRef.current)
      const visibleIds = current
        .filter((item) => !moving.has(item.id))
        .map((item) => item.id)
      const rects = visibleIds
        .map((id) => {
          const node = itemNodes.current.get(id)
          if (!node) return null
          const rect = node.getBoundingClientRect()
          return {
            id,
            top: rect.top,
            bottom: rect.bottom,
            height: rect.height,
          }
        })
        .filter((entry): entry is NonNullable<typeof entry> => entry !== null)
      const insertIndex = indexFromPointerY(event.clientY, rects)
      pendingToIndex.current = insertIndex
      if (dropIndicators) {
        setDropIndicator(dropIndicatorFromInsertIndex(insertIndex, visibleIds))
      }
      autoScrollSession.current?.updatePointer(event.clientX, event.clientY)
      if (overlay) {
        setOverlayState({
          active: true,
          activeId,
          ids: movingIdsRef.current,
          count: movingIdsRef.current.length,
          x: event.clientX,
          y: event.clientY,
        })
      }
    }

    const onUp = (event: PointerEvent) => {
      if (event.pointerId !== pointerId.current) return
      const current = itemsRef.current
      const to = pendingToIndex.current
      const movingIds = movingIdsRef.current
      pointerId.current = null
      pendingToIndex.current = null
      setActiveId(null)
      clearDragChrome()
      if (to === null || movingIds.length === 0) {
        announce("Reorder finished")
        return
      }
      commitMove(current, movingIds, to)
    }

    window.addEventListener("pointermove", onMove)
    window.addEventListener("pointerup", onUp)
    window.addEventListener("pointercancel", onUp)
    return () => {
      window.removeEventListener("pointermove", onMove)
      window.removeEventListener("pointerup", onUp)
      window.removeEventListener("pointercancel", onUp)
      stopAutoScroll()
    }
  }, [
    activeId,
    announce,
    clearDragChrome,
    commitMove,
    dropIndicators,
    overlay,
    stopAutoScroll,
  ])

  const getItemProps = useCallback(
    (id: string): SortableItemBindings => {
      const index = items.findIndex((item) => item.id === id)
      const inPayload = dragIds.includes(id)
      const isDragging =
        activeId === id || keyboardActiveId === id || inPayload
      const isPlaceholder = Boolean(overlay && activeId && inPayload)
      const reduced = prefersReducedMotion()
      const indicatorPlacement =
        dropIndicators && dropIndicator.targetId === id
          ? (dropIndicator.placement ?? undefined)
          : undefined

      return {
        ref: (node) => setNode(id, node),
        isDragging,
        isPlaceholder,
        style: {
          opacity: isPlaceholder
            ? undefined
            : isDragging
              ? "var(--opacity-subtle)"
              : undefined,
          transform:
            !overlay && isDragging && activeId === id && !reduced
              ? "scale(var(--df-dnd-lift-scale))"
              : undefined,
          transition: reduced
            ? "none"
            : "transform var(--df-duration-quick) var(--df-ease-standard), opacity var(--df-duration-quick) var(--df-ease-standard)",
          touchAction: "none",
          zIndex: isDragging && !overlay ? "var(--z-raised)" : undefined,
        },
        attributes: {
          role: "button",
          tabIndex: disabled ? -1 : 0,
          "aria-roledescription": "sortable",
          "aria-grabbed": isDragging,
          "aria-describedby": instructionsId,
          ...(isPlaceholder ? { "data-df-dnd-placeholder": true } : null),
          ...(indicatorPlacement
            ? { "data-df-drop-indicator": indicatorPlacement }
            : null),
        },
        listeners: {
          onPointerDown: (event) => {
            if (disabled || event.button !== 0) return
            event.preventDefault()
            const movingIds = resolveMovingIds(id, items)
            pointerId.current = event.pointerId
            pendingToIndex.current = index
            movingIdsRef.current = movingIds
            setDragIds(movingIds)
            setActiveId(id)
            setKeyboardActiveId(null)
            startAutoScroll(event.currentTarget as HTMLElement)
            if (overlay) {
              setOverlayState({
                active: true,
                activeId: id,
                ids: movingIds,
                count: movingIds.length,
                x: event.clientX,
                y: event.clientY,
              })
            }
            announce(
              movingIds.length > 1
                ? `Picked up ${movingIds.length} items`
                : `Picked up item ${index + 1} of ${items.length}`
            )
            ;(event.currentTarget as HTMLElement).setPointerCapture?.(
              event.pointerId
            )
          },
          onKeyDown: (event) => {
            if (disabled) return
            if (event.key === " " || event.key === "Enter") {
              event.preventDefault()
              if (keyboardActiveId === id) {
                setKeyboardActiveId(null)
                clearDragChrome()
                announce("Item dropped")
                return
              }
              const movingIds = resolveMovingIds(id, items)
              movingIdsRef.current = movingIds
              setDragIds(movingIds)
              setKeyboardActiveId(id)
              setActiveId(null)
              announce(
                movingIds.length > 1
                  ? `${movingIds.length} items grabbed. Use up and down arrows to reorder, Space to drop, Escape to cancel.`
                  : "Item grabbed. Use up and down arrows to reorder, Space to drop, Escape to cancel."
              )
              return
            }
            if (keyboardActiveId !== id) return
            if (event.key === "Escape") {
              event.preventDefault()
              setKeyboardActiveId(null)
              clearDragChrome()
              announce("Reorder cancelled")
              return
            }
            if (event.key === "ArrowUp" || event.key === "ArrowDown") {
              event.preventDefault()
              const movingIds =
                movingIdsRef.current.length > 0
                  ? movingIdsRef.current
                  : resolveMovingIds(id, items)
              const delta = event.key === "ArrowUp" ? -1 : 1
              if (movingIds.length <= 1) {
                const from = items.findIndex((item) => item.id === id)
                if (from < 0) return
                const to = from + delta
                if (to < 0 || to >= items.length) return
                const next = moveIndex(items, from, to)
                onReorder(next)
                onDropCommit?.({
                  items: next,
                  movingIds,
                  insertIndex: to,
                })
                announce(`Moved item to position ${to + 1} of ${items.length}`)
                return
              }
              const firstId = movingIds[0]
              if (!firstId) return
              let insertAmongRemaining = 0
              for (const item of items) {
                if (item.id === firstId) break
                if (!movingIds.includes(item.id)) insertAmongRemaining += 1
              }
              const remainingCount = items.length - movingIds.length
              const nextInsert = insertAmongRemaining + delta
              if (nextInsert < 0 || nextInsert > remainingCount) return
              commitMove(items, movingIds, nextInsert)
            }
          },
        },
      }
    },
    [
      activeId,
      announce,
      clearDragChrome,
      commitMove,
      disabled,
      dragIds,
      dropIndicator.placement,
      dropIndicator.targetId,
      dropIndicators,
      instructionsId,
      items,
      keyboardActiveId,
      onDropCommit,
      onReorder,
      overlay,
      resolveMovingIds,
      setNode,
      startAutoScroll,
    ]
  )

  return {
    activeId: activeId ?? keyboardActiveId,
    getItemProps,
    instructionsId,
    instructions:
      "Press Space or Enter to pick up an item, Arrow keys to move, Space or Enter to drop, Escape to cancel.",
    liveMessage,
    overlay: overlayState,
    dropIndicator,
    movingIds: dragIds,
  }
}

"use client"

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type RefObject,
} from "react"

import { type AutoScrollAxis } from "./auto-scroll"
import {
  disposeAutoScrollSession,
  findScrollableAncestor,
  startAutoScrollSession,
  type AutoScrollSession,
} from "./auto-scroll-runtime"
import {
  inactiveDragOverlayState,
  type DragOverlayState,
} from "./drag-overlay"
import {
  dropIndicatorFromInsertIndex,
  EMPTY_DROP_INDICATOR,
  type DropIndicatorState,
} from "./drop-indicator"
import { prefersReducedMotion } from "./motion"
import { indexFromPointerY } from "./reorder"
import {
  applyTreeDrop,
  DF_DND_TREE_INDENT_PX,
  resolveTreeDrop,
  type TreeDropTarget,
  type TreeFlatNode,
} from "./tree"

export type TreeDndAutoScrollOption =
  | boolean
  | {
      containerRef?: RefObject<HTMLElement | null>
      axis?: AutoScrollAxis
    }

export type TreeItemBindings = {
  ref: (node: HTMLElement | null) => void
  style: CSSProperties
  isDragging: boolean
  isPlaceholder: boolean
  attributes: {
    role: "button"
    tabIndex: number
    "aria-roledescription": string
    "aria-grabbed": boolean
    "aria-describedby": string
    "data-df-dnd-placeholder"?: boolean
    "data-df-drop-indicator"?: "before" | "after" | "into"
    "data-df-tree-depth": number
  }
  listeners: {
    onPointerDown: (event: ReactPointerEvent) => void
    onKeyDown: (event: KeyboardEvent) => void
  }
}

/**
 * Nested list reorder foundation over a flat `{ id, parentId, depth }` array.
 * Pointer x offset resolves indent and outdent; Y uses the sortable insert index.
 */
export function useTreeDnd<T extends TreeFlatNode>(options: {
  nodes: readonly T[]
  onChange: (nodes: readonly T[]) => void
  disabled?: boolean
  indentThreshold?: number
  autoScroll?: TreeDndAutoScrollOption
  overlay?: boolean
  dropIndicators?: boolean
  onDropCommit?: (commit: {
    nodes: readonly T[]
    activeId: string
    target: TreeDropTarget
  }) => void
}) {
  const {
    nodes,
    onChange,
    disabled = false,
    indentThreshold = DF_DND_TREE_INDENT_PX,
    autoScroll = false,
    overlay = false,
    dropIndicators = false,
    onDropCommit,
  } = options
  const instructionsId = useId()
  const itemNodes = useRef(new Map<string, HTMLElement>())
  const listNode = useRef<HTMLElement | null>(null)
  const nodesRef = useRef(nodes)

  useEffect(() => {
    nodesRef.current = nodes
  }, [nodes])

  const [activeId, setActiveId] = useState<string | null>(null)
  const [keyboardActiveId, setKeyboardActiveId] = useState<string | null>(null)
  const [liveMessage, setLiveMessage] = useState("")
  const [overlayState, setOverlayState] = useState<DragOverlayState>(
    inactiveDragOverlayState
  )
  const [dropIndicator, setDropIndicator] =
    useState<DropIndicatorState>(EMPTY_DROP_INDICATOR)
  const [pendingTarget, setPendingTarget] = useState<TreeDropTarget | null>(
    null
  )
  const pointerId = useRef<number | null>(null)
  const pendingRef = useRef<TreeDropTarget | null>(null)
  const pointerOffsetX = useRef(0)
  const autoScrollSession = useRef<AutoScrollSession | null>(null)

  const setNode = useCallback((id: string, node: HTMLElement | null) => {
    if (node) itemNodes.current.set(id, node)
    else itemNodes.current.delete(id)
  }, [])

  const announce = useCallback((message: string) => {
    setLiveMessage(message)
  }, [])

  const stopAutoScroll = useCallback(() => {
    disposeAutoScrollSession(autoScrollSession)
  }, [])

  const startAutoScroll = useCallback(
    (origin: HTMLElement | null) => {
      if (!autoScroll) return
      stopAutoScroll()
      const config = typeof autoScroll === "object" ? autoScroll : {}
      const axis = config.axis ?? "y"
      autoScrollSession.current = startAutoScrollSession({
        axis,
        getContainer: () =>
          config.containerRef?.current ??
          findScrollableAncestor(origin, axis),
      })
    },
    [autoScroll, stopAutoScroll]
  )

  const clearDragChrome = useCallback(() => {
    setOverlayState(inactiveDragOverlayState())
    setDropIndicator(EMPTY_DROP_INDICATOR)
    setPendingTarget(null)
    pendingRef.current = null
    stopAutoScroll()
  }, [stopAutoScroll])

  const resolveFromPointer = useCallback(
    (clientX: number, clientY: number, id: string) => {
      const current = nodesRef.current
      const listLeft =
        listNode.current?.getBoundingClientRect().left ??
        itemNodes.current.get(id)?.getBoundingClientRect().left ??
        clientX
      pointerOffsetX.current = clientX - listLeft
      const visible = current.filter((node) => node.id !== id)
      const rects = visible
        .map((node) => {
          const element = itemNodes.current.get(node.id)
          if (!element) return null
          const rect = element.getBoundingClientRect()
          return {
            id: node.id,
            top: rect.top,
            bottom: rect.bottom,
            height: rect.height,
          }
        })
        .filter((entry): entry is NonNullable<typeof entry> => entry !== null)
      const insertIndex = indexFromPointerY(clientY, rects)
      const target = resolveTreeDrop({
        nodes: current,
        activeId: id,
        insertIndex,
        pointerOffsetX: pointerOffsetX.current,
        indentThreshold,
      })
      pendingRef.current = target
      setPendingTarget(target)
      if (!target) {
        setDropIndicator(EMPTY_DROP_INDICATOR)
        return null
      }
      if (dropIndicators) {
        const visibleIds = visible.map((node) => node.id)
        const base = dropIndicatorFromInsertIndex(insertIndex, visibleIds)
        if (target.depth > 0 && insertIndex > 0) {
          const previous = visible[insertIndex - 1]
          if (previous && target.targetParentId === previous.id) {
            setDropIndicator({ targetId: previous.id, placement: "into" })
            return target
          }
        }
        setDropIndicator(base)
      }
      return target
    },
    [dropIndicators, indentThreshold]
  )

  useEffect(() => {
    if (pointerId.current === null || !activeId) return

    const onMove = (event: PointerEvent) => {
      if (event.pointerId !== pointerId.current) return
      resolveFromPointer(event.clientX, event.clientY, activeId)
      autoScrollSession.current?.updatePointer(event.clientX, event.clientY)
      if (overlay) {
        setOverlayState({
          active: true,
          activeId,
          ids: [activeId],
          count: 1,
          x: event.clientX,
          y: event.clientY,
        })
      }
    }

    const onUp = (event: PointerEvent) => {
      if (event.pointerId !== pointerId.current) return
      const current = nodesRef.current
      const target = pendingRef.current
      pointerId.current = null
      setActiveId(null)
      clearDragChrome()
      if (!target) {
        announce("Tree reorder finished")
        return
      }
      const next = applyTreeDrop(current, activeId, target)
      const unchanged =
        next.length === current.length &&
        next.every(
          (node, index) =>
            node.id === current[index]?.id &&
            node.parentId === current[index]?.parentId &&
            node.depth === current[index]?.depth
        )
      if (unchanged) {
        announce("Tree reorder finished")
        return
      }
      onChange(next)
      onDropCommit?.({ nodes: next, activeId, target })
      announce(`Moved item to depth ${target.depth + 1}`)
    }

    window.addEventListener("pointermove", onMove)
    window.addEventListener("pointerup", onUp)
    window.addEventListener("pointercancel", onUp)
    return () => {
      window.removeEventListener("pointermove", onMove)
      window.removeEventListener("pointerup", onUp)
      window.removeEventListener("pointercancel", onUp)
      stopAutoScroll()
    }
  }, [
    activeId,
    announce,
    clearDragChrome,
    onChange,
    onDropCommit,
    overlay,
    resolveFromPointer,
    stopAutoScroll,
  ])

  const getListProps = useCallback(
    () => ({
      ref: (node: HTMLElement | null) => {
        listNode.current = node
      },
    }),
    []
  )

  const getItemProps = useCallback(
    (id: string): TreeItemBindings => {
      const node = nodes.find((entry) => entry.id === id)
      const depth = node?.depth ?? 0
      const isDragging = activeId === id || keyboardActiveId === id
      const isPlaceholder = Boolean(overlay && activeId === id)
      const reduced = prefersReducedMotion()
      const indicatorPlacement =
        dropIndicators && dropIndicator.targetId === id
          ? (dropIndicator.placement ?? undefined)
          : undefined

      return {
        ref: (element) => setNode(id, element),
        isDragging,
        isPlaceholder,
        style: {
          opacity: isPlaceholder
            ? undefined
            : isDragging
              ? "var(--opacity-subtle)"
              : undefined,
          transform:
            !overlay && isDragging && activeId === id && !reduced
              ? "scale(var(--df-dnd-lift-scale))"
              : undefined,
          transition: reduced
            ? "none"
            : "transform var(--df-duration-quick) var(--df-ease-standard), opacity var(--df-duration-quick) var(--df-ease-standard)",
          touchAction: "none",
          zIndex: isDragging && !overlay ? "var(--z-raised)" : undefined,
        },
        attributes: {
          role: "button",
          tabIndex: disabled ? -1 : 0,
          "aria-roledescription": "tree item",
          "aria-grabbed": isDragging,
          "aria-describedby": instructionsId,
          "data-df-tree-depth": depth,
          ...(isPlaceholder ? { "data-df-dnd-placeholder": true } : null),
          ...(indicatorPlacement
            ? { "data-df-drop-indicator": indicatorPlacement }
            : null),
        },
        listeners: {
          onPointerDown: (event) => {
            if (disabled || event.button !== 0) return
            event.preventDefault()
            pointerId.current = event.pointerId
            setActiveId(id)
            setKeyboardActiveId(null)
            startAutoScroll(event.currentTarget as HTMLElement)
            resolveFromPointer(event.clientX, event.clientY, id)
            if (overlay) {
              setOverlayState({
                active: true,
                activeId: id,
                ids: [id],
                count: 1,
                x: event.clientX,
                y: event.clientY,
              })
            }
            announce("Picked up tree item")
            ;(event.currentTarget as HTMLElement).setPointerCapture?.(
              event.pointerId
            )
          },
          onKeyDown: (event) => {
            if (disabled) return
            if (event.key === " " || event.key === "Enter") {
              event.preventDefault()
              if (keyboardActiveId === id) {
                setKeyboardActiveId(null)
                clearDragChrome()
                announce("Tree item dropped")
                return
              }
              setKeyboardActiveId(id)
              setActiveId(null)
              announce(
                "Tree item grabbed. Arrow up and down reorder. Arrow left and right change depth. Space drops. Escape cancels."
              )
              return
            }
            if (keyboardActiveId !== id) return
            if (event.key === "Escape") {
              event.preventDefault()
              setKeyboardActiveId(null)
              clearDragChrome()
              announce("Tree reorder cancelled")
              return
            }
            const index = nodes.findIndex((entry) => entry.id === id)
            if (index < 0) return
            const current = nodes[index]
            if (!current) return
            if (event.key === "ArrowUp" || event.key === "ArrowDown") {
              event.preventDefault()
              const siblings = nodes.filter(
                (entry) => entry.parentId === current.parentId
              )
              const siblingIndex = siblings.findIndex((entry) => entry.id === id)
              const nextSiblingIndex =
                event.key === "ArrowUp" ? siblingIndex - 1 : siblingIndex + 1
              if (
                nextSiblingIndex < 0 ||
                nextSiblingIndex >= siblings.length
              ) {
                return
              }
              const target: TreeDropTarget = {
                targetParentId: current.parentId,
                index: nextSiblingIndex,
                depth: current.depth,
              }
              const next = applyTreeDrop(nodes, id, target)
              onChange(next)
              onDropCommit?.({ nodes: next, activeId: id, target })
              announce(`Moved tree item to position ${nextSiblingIndex + 1}`)
              return
            }
            if (event.key === "ArrowRight") {
              event.preventDefault()
              if (index === 0) return
              const previous = nodes[index - 1]
              if (!previous || previous.depth !== current.depth) return
              const target: TreeDropTarget = {
                targetParentId: previous.id,
                index: 0,
                depth: current.depth + 1,
              }
              const next = applyTreeDrop(nodes, id, target)
              onChange(next)
              onDropCommit?.({ nodes: next, activeId: id, target })
              announce("Indented tree item")
              return
            }
            if (event.key === "ArrowLeft") {
              event.preventDefault()
              if (current.depth === 0 || current.parentId == null) return
              const parent = nodes.find(
                (entry) => entry.id === current.parentId
              )
              if (!parent) return
              const parentSiblingIndex =
                nodes
                  .filter((entry) => entry.parentId === parent.parentId)
                  .findIndex((entry) => entry.id === parent.id) + 1
              const target: TreeDropTarget = {
                targetParentId: parent.parentId,
                index: parentSiblingIndex,
                depth: parent.depth,
              }
              const next = applyTreeDrop(nodes, id, target)
              onChange(next)
              onDropCommit?.({ nodes: next, activeId: id, target })
              announce("Outdented tree item")
            }
          },
        },
      }
    },
    [
      activeId,
      announce,
      clearDragChrome,
      disabled,
      dropIndicator.placement,
      dropIndicator.targetId,
      dropIndicators,
      instructionsId,
      keyboardActiveId,
      nodes,
      onChange,
      onDropCommit,
      overlay,
      resolveFromPointer,
      setNode,
      startAutoScroll,
    ]
  )

  return {
    activeId: activeId ?? keyboardActiveId,
    getItemProps,
    getListProps,
    instructionsId,
    instructions:
      "Press Space or Enter to pick up a tree item. Arrow up and down reorder. Arrow left and right change depth. Space drops. Escape cancels.",
    liveMessage,
    overlay: overlayState,
    dropIndicator,
    pendingTarget,
  }
}

"use client"

import { useMemo } from "react"
import { useVirtualizer } from "@tanstack/react-virtual"

export type VirtualRowItem = {
  index: number
  key: string | number | bigint
  start: number
  end: number
  size: number
}

export type UseVirtualRowsOptions = {
  count: number
  estimateSize: number | ((index: number) => number)
  getScrollElement: () => Element | null
  overscan?: number | undefined
}

export type UseVirtualRowsResult = {
  items: VirtualRowItem[]
  totalSize: number
  measureElement: (node: Element | null | undefined) => void
}

/** Normalize a fixed or per index size into the estimator shape the windowing engine expects. */
export function resolveEstimateSize(
  estimateSize: UseVirtualRowsOptions["estimateSize"]
): (index: number) => number {
  if (typeof estimateSize === "number") {
    const size = estimateSize
    return () => size
  }
  return estimateSize
}

/**
 * Owned row windowing hook. Kit consumers import this module instead of the
 * underlying windowing package.
 */
export function useVirtualRows(
  options: UseVirtualRowsOptions
): UseVirtualRowsResult {
  const estimateSize = useMemo(
    () => resolveEstimateSize(options.estimateSize),
    [options.estimateSize]
  )

  // Consumers pass measureElement as a ref callback and do not feed windowing
  // callbacks into memoized props, so the unsafe-memoization caveat does not apply.
  // eslint-disable-next-line react-hooks/incompatible-library -- see above
  const virtualizer = useVirtualizer({
    count: options.count,
    estimateSize,
    getScrollElement: options.getScrollElement,
    ...(options.overscan !== undefined ? { overscan: options.overscan } : {}),
  })

  return {
    items: virtualizer.getVirtualItems(),
    totalSize: virtualizer.getTotalSize(),
    measureElement: (node) => virtualizer.measureElement(node ?? null),
  }
}
